                          <span className="text-[10px] bg-amber-100 text-amber-800 font-semibold px-2 py-0.5 rounded-full">
                            Rascunho
                          </span>
                        )}

                        {patient?.google_doc_id && (
                          evo.google_doc_append_status === 'completed' ? (
                            <span className="text-[10px] bg-blue-50 text-blue-700 border border-blue-100 font-semibold px-2 py-0.5 rounded-full flex items-center gap-1">
                              <FileText size={10} />
                              <span>Google Docs</span>
                            </span>
                          ) : (
                            <span className="text-[10px] bg-stone-100 text-stone-500 font-semibold px-2 py-0.5 rounded-full flex items-center gap-1" title="Não salvo no Google Docs">
                              <CloudOff size={10} />
                              <span>Apenas Local</span>
                            </span>
                          )
                        )}
                      </div>
                      <Link to={`/painel/patients/${evo.patient_id}`} className="text-brand-primary hover:text-brand-primary-hover hover:underline font-semibold text-lg">
                        {patient?.full_name || 'Paciente Desconhecido'}
                      </Link>
                    </div>

                    <div className="flex items-center gap-2">
                      <div className="flex items-center gap-2 relative">
                        {evo.status === 'signed' && (
                          <button
                            type="button"
                            onClick={async () => {
                              let logoBase64 = null;
                              const currentLogoUrl = getLogoUrl();
                              if (currentLogoUrl) {
                                try {
                                  logoBase64 = await getBase64ImageFromUrl(currentLogoUrl);
                                } catch (err) {
                                  console.error("Error preloading logo:", err);
                                }
                              }
                              const doc = generateEvolutionPDF(evo, patient, professional, logoBase64);
                              const cleanPatientName = (patient?.full_name || 'Paciente').replace(/\s+/g, '_');
                              const cleanDate = evo.session_date
                                ? evo.session_date.split('-').reverse().join('-')
                                : new Date(evo.created_at).toLocaleDateString('pt-BR').replace(/\//g, '-');
                              const saved = await downloadPdfFile(doc, `Evolucao_Clinica_${cleanPatientName}_${cleanDate}.pdf`);
                              if (!saved) {
                                alert('Não foi possível baixar o PDF. Verifique o armazenamento do dispositivo e tente novamente.');
                              }
                            }}
                            className="btn-outline py-1.5 px-3 text-xs flex items-center space-x-1.5 border-emerald-200 bg-emerald-50 text-emerald-700 hover:bg-emerald-100 cursor-pointer font-semibold rounded-xl"
                            title="Baixar PDF do Prontuário Assinado"
                          >
                            <Download size={14} />
                            <span>Baixar PDF</span>
                          </button>
                        )}

                        <button
                          type="button"
                          onClick={() => setActiveDropdownId(activeDropdownId === evo.id ? null : evo.id)}
                          className="btn-outline h-8 w-8 p-0 flex items-center justify-center border-brand-border bg-white text-brand-text hover:bg-gray-50 rounded-xl cursor-pointer"
                          title="Mais opções"
                        >
                          <MoreVertical size={16} />
                        </button>

                        {activeDropdownId === evo.id && (
                          <>
                            <div className="fixed inset-0 z-10" onClick={() => setActiveDropdownId(null)} />
                            <div className="absolute right-0 top-9 w-72 bg-white border border-brand-border rounded-xl shadow-lg py-1.5 z-20 animate-in fade-in slide-in-from-top-1 duration-150">
                              {/* 1. Salvar no Google Docs (se configurado e pendente) */}
                              {patient?.google_doc_id && evo.google_doc_append_status !== 'completed' && (
                                <button
                                  type="button"
                                  onClick={() => {
                                    setActiveDropdownId(null);
                                    handleSaveToGoogleDocs(evo);
                                  }}
                                  className="w-full text-left px-4 py-2 hover:bg-brand-bg flex items-start space-x-2.5 transition-colors cursor-pointer"
                                >
                                  <FileText size={15} className="text-blue-600 mt-0.5 shrink-0" />
                                  <div className="flex flex-col">
                                    <span className="text-xs font-semibold text-brand-text">Enviar Texto ao Prontuário</span>
                                    <span className="text-[10px] text-stone-400 font-normal mt-0.5 leading-tight">Adiciona o text desta evolução ao prontuário no Google Docs</span>
                                  </div>
                                </button>
                              )}

                              {/* 2. Salvar no Drive (se assinado e com pasta configurada) */}
                              {evo.status === 'signed' && hasClinicalAccess && googleAccessToken && patient?.target_folder_id && (
                                <button
                                  type="button"
                                  onClick={async () => {
                                    setActiveDropdownId(null);
                                    let logoBase64 = null;
                                    const currentLogoUrl = getLogoUrl();
                                    if (currentLogoUrl) {
                                      try {
                                        logoBase64 = await getBase64ImageFromUrl(currentLogoUrl);
                                      } catch (err) {
                                        console.error("Error preloading logo:", err);
                                      }
                                    }
                                    const doc = generateEvolutionPDF(evo, patient, professional, logoBase64);
                                    const pdfBlob = doc.output('blob');
                                    const cleanPatientName = (patient?.full_name || 'Paciente').replace(/\s+/g, '_');
                                    const cleanDate = evo.session_date
                                      ? evo.session_date.split('-').reverse().join('-')
                                      : new Date(evo.created_at).toLocaleDateString('pt-BR').replace(/\//g, '-');
                                    const fileName = `Evolucao_Clinica_${cleanPatientName}_${cleanDate}.pdf`;
                                    try {
                                      await uploadPdfToGoogleDrive(googleAccessToken, pdfBlob, fileName, patient.target_folder_id);

                                      const { error: updateError } = await supabase
                                        .from('evolutions')
                                        .update({
                                          google_doc_append_status: 'completed',
                                          google_doc_append_at: new Date().toISOString()
                                        })
                                        .eq('id', evo.id);
                                      if (updateError) throw updateError;

                                      alert("PDF da evolução salvo com sucesso na pasta do paciente no Google Drive!");
                                      await fetchHistory();
                                    } catch (err: any) {
                                      console.error("Error uploading PDF:", err);
                                      alert("Erro ao salvar PDF: " + (err.message || err));
                                    }
                                  }}
                                  className="w-full text-left px-4 py-2 hover:bg-brand-bg flex items-start space-x-2.5 transition-colors cursor-pointer"
                                >
                                  <ExternalLink size={15} className="text-emerald-600 mt-0.5 shrink-0" />
                                  <div className="flex flex-col">
                                    <span className="text-xs font-semibold text-brand-text">Salvar PDF Assinado no Drive</span>
                                    <span className="text-[10px] text-stone-400 font-normal mt-0.5 leading-tight">Salva uma cópia oficial em PDF na pasta do Google Drive</span>
                                  </div>
                                </button>
                              )}

                              {/* 3. Acessar Documento */}
                              {patient?.google_doc_id && (
                                <a
                                  href={`https://docs.google.com/document/d/${patient.google_doc_id}/edit`}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  onClick={() => setActiveDropdownId(null)}
                                  className="w-full text-left px-4 py-2 hover:bg-brand-bg flex items-start space-x-2.5 transition-colors cursor-pointer"
                                >
                                  <FileText size={15} className="text-blue-500 mt-0.5 shrink-0" />
                                  <div className="flex flex-col">
                                    <span className="text-xs font-semibold text-brand-text">Abrir Prontuário (Google Docs)</span>
                                    <span className="text-[10px] text-stone-400 font-normal mt-0.5 leading-tight">Acessa o documento de prontuário integrado do paciente</span>
                                  </div>
                                </a>
                              )}

                              {/* 4. Imprimir */}
                              <button
                                type="button"
                                onClick={() => {
                                  setActiveDropdownId(null);
                                  handlePrintEvolution(evo);
                                }}
                                className="w-full text-left px-4 py-2 hover:bg-brand-bg flex items-start space-x-2.5 transition-colors cursor-pointer"
                              >
                                <Printer size={15} className="text-stone-500 mt-0.5 shrink-0" />
                                <div className="flex flex-col">
                                  <span className="text-xs font-semibold text-brand-text">Imprimir / PDF Local</span>
                                  <span className="text-[10px] text-stone-400 font-normal mt-0.5 leading-tight">Gera versão para impressão ou download local</span>
                                </div>
                              </button>

                              {/* 5. Acessar Paciente */}
                              <Link
                                to={`/painel/patients/${evo.patient_id}`}
                                onClick={() => setActiveDropdownId(null)}
                                className="w-full text-left px-4 py-2 hover:bg-brand-bg flex items-start space-x-2.5 transition-colors cursor-pointer border-t border-brand-border/40 mt-1 pt-1.5"
                              >
                                <User size={15} className="text-brand-primary mt-0.5 shrink-0" />
                                <div className="flex flex-col">
                                  <span className="text-xs font-semibold text-brand-text">Ver Perfil do Paciente</span>
                                  <span className="text-[10px] text-stone-400 font-normal mt-0.5 leading-tight">Acessa a ficha completa e histórico deste paciente</span>
                                </div>
                              </Link>
                            </div>
                          </>
                        )}
                      </div>
                    </div>
                  </div>

                  {evo.transcription_text && (
                    <div className="mt-4 text-sm text-brand-text-muted bg-brand-bg p-4 rounded-xl border border-brand-border space-y-2">
                      <p className="line-clamp-2">{evo.transcription_text}</p>
                      <div className="flex flex-col md:flex-row justify-between items-start md:items-center text-[10px] gap-2 pt-2 border-t border-brand-border/40">
                        {evo.status === 'signed' ? (
                          <div className="text-emerald-700 flex items-center space-x-1.5">
                            <Shield size={12} className="text-emerald-500 shrink-0" />
                            <span>Assinado Digitalmente ({evo.signature_method === 'govbr' ? 'Gov.br' : 'Chave do App'}) em {formatDateTime(evo.signature_date)}</span>
                          </div>
                        ) : (
                          <div className="text-amber-700 flex items-center space-x-1.5">
                            <span>Rascunho</span>
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>

    {/* Portal de Impressão de prontuário/relatório (fora do #root do App) */}
    {printMode && createPortal(
      <div id="print-area">
        {/* Logo/Timbre fictício */}
        <div className="flex justify-between items-center border-b-2 border-brand-primary pb-3 mb-6">
          <div className="flex items-center gap-4">
            {getLogoUrl() ? (
              <div className="bg-white p-1 rounded border border-stone-100 flex items-center justify-center">
                <img src={getLogoUrl()} alt="Logo" className="object-contain bg-white" style={{ backgroundColor: '#ffffff', height: getLogoPrintHeight() }} />
              </div>
            ) : (
              <h1 className="text-xl font-display font-bold text-brand-primary leading-none">{siteConfig.pwa_app_name || "Evolução Clínica"}</h1>
            )}
            <div className="border-l border-stone-300 pl-4 py-0.5 flex flex-col justify-center">
              <span className="text-[20px] font-bold text-stone-800 leading-tight" style={{ fontFamily: 'Outfit, ui-sans-serif, system-ui, sans-serif' }}>
                Plataforma Inteligente de Acompanhamento Terapêutico
              </span>
              <span className="text-[10px] text-stone-500 font-medium leading-none mt-1">
                Emitido por evolucaoclinica.app.br
              </span>
            </div>
          </div>
          <div className="text-right text-xs shrink-0">
            <p className="font-bold text-brand-text">Paciente: {printPatientName}</p>
          </div>
        </div>

        <div className="flex justify-between items-start text-xs border-b border-brand-border pb-4 mb-6">
          <div>
            <p className="font-semibold text-brand-text uppercase tracking-wider text-[10px] text-brand-text-muted mb-1">Documento</p>
            <p className="font-semibold text-sm text-brand-primary">{printDocType}</p>
          </div>
          <div className="text-right">
            <p className="font-semibold text-brand-text uppercase tracking-wider text-[10px] text-brand-text-muted mb-1">Profissional Responsável</p>
            <p className="font-semibold text-brand-text">{professional?.full_name}</p>
            {professional?.professional_register && (
              <p className="text-brand-text-muted text-[10px]">{professional.professional_register}</p>
            )}
          </div>
        </div>

        {/* Conteudo Dinâmico */}
        <div className="whitespace-pre-wrap font-sans text-sm text-stone-800 leading-relaxed">
          {prontuarioDocContent}
        </div>

        {/* Assinatura / Rodapé */}
        {printSignatureInfo ? (
          <div className="mt-12 pt-4 border-t-2 border-dashed border-emerald-300 bg-emerald-50/50 p-4 rounded-xl text-xs space-y-2 text-stone-800" style={{ pageBreakInside: 'avoid', breakInside: 'avoid' }}>
            <div className="flex items-center space-x-2 text-emerald-700 font-bold">
              <Shield size={14} className="text-emerald-600" />
              <span>DOCUMENTO ASSINADO DIGITALMENTE VIA CHAVE DO APLICATIVO</span>
            </div>
            <p>O profissional acima declarou a autoria deste registro clínico no sistema em conformidade com as diretrizes do conselho federal de sua categoria.</p>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-[10px] text-stone-600 font-mono mt-2 bg-white/70 p-2.5 rounded-lg border border-emerald-100">
              <p><strong>Assinado por:</strong> {printSignatureInfo.name || professional?.full_name} ({printSignatureInfo.register || professional?.professional_register})</p>
              <p><strong>Data/Hora Assinatura:</strong> {new Date(printSignatureInfo.date).toLocaleString('pt-BR')}</p>
              <p><strong>IP de Origem:</strong> {printSignatureInfo.ip}</p>
              <p className="sm:col-span-2 break-all"><strong>Hash SHA-256:</strong> {printSignatureInfo.hash}</p>
            </div>
          </div>
        ) : (
          <div className="mt-16 pt-8 flex flex-col items-center" style={{ pageBreakInside: 'avoid', breakInside: 'avoid' }}>
            <div className="w-48 border-b border-brand-text-muted/30"></div>
            <p className="text-xs font-semibold text-brand-text mt-2">{professional?.full_name}</p>
            <p className="text-[10px] text-brand-text-muted">{professional?.professional_register}</p>
          </div>
        )}
      </div>,
      document.body
    )}
    </>
  );
}

