import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuthStore } from '../store/authStore';
import { 
  Sparkles, 
  Mic, 
  Files, 
  ShieldCheck, 
  Check, 
  ChevronDown, 
  ArrowRight, 
  Lock, 
  Play, 
  Users, 
  Calendar, 
  FileText, 
  Send,
  HelpCircle,
  Menu,
  X,
  Plus,
  Brain,
  Volume2,
  GraduationCap,
  Activity,
  Stethoscope,
  TrendingUp,
  Clock,
  Coins,
  Database,
  AlertCircle,
  ChevronUp,
  Loader2,
  Smartphone,
  Download,
  ArrowUpRight,
  Share2
} from 'lucide-react';
import { APP_VERSION, PLAY_STORE_VERSION } from '../components/layout/AppVersion';
import { useSiteConfig } from '../hooks/useSiteConfig';
import { appendBrandAssetVersion, getBrandAssetSignature } from '../utils/brandAssets';
import { LEGAL_SUPPORT_EMAIL } from '../utils/legal';
import { supabase } from '../supabaseClient';
import { FeatureTooltip } from '../components/common/FeatureTooltip';
import { MONTHLY_PLAN_FEATURES, YEARLY_PLAN_FEATURES } from '../config/subscriptionPlans';
import { getCurrentAcquisitionData } from '../utils/acquisitionTracking';

const DEFAULT_PLANS = [
  {
    id: 'monthly',
    name: 'Plano Mensal',
    price: 39.00,
    original_price: null,
    equivalent_monthly_price: null,
    discount_text: null,
    launch_offer_text: null,
    tag_text: 'Mês a Mês',
    description: 'Flexibilidade para experimentar sem amarras contratuais.',
    features: MONTHLY_PLAN_FEATURES
  },
  {
    id: 'yearly',
    name: 'Plano Anual',
    price: 199.00,
    original_price: null,
    equivalent_monthly_price: 16.58,
    discount_text: '57% OFF',
    launch_offer_text: null,
    tag_text: 'Popular',
    description: 'A alternativa perfeita para consolidar sua economia anual.',
    features: YEARLY_PLAN_FEATURES
  }
];

export default function LandingPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const siteConfig = useSiteConfig();
  const assetSignature = getBrandAssetSignature(siteConfig);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [faqOpen, setFaqOpen] = useState<number | null>(null);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [showWhatsappTooltip, setShowWhatsappTooltip] = useState(false);
  const [isWhatsappFormOpen, setIsWhatsappFormOpen] = useState(false);
  const [leadName, setLeadName] = useState('');
  const [leadPhone, setLeadPhone] = useState('');
  const [leadMessage, setLeadMessage] = useState('');
  const [submittingLead, setSubmittingLead] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      // Exibe tooltip somente se o form não estiver aberto
      if (!isWhatsappFormOpen) {
        setShowWhatsappTooltip(true);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [isWhatsappFormOpen]);

  const handleOpenWhatsappForm = () => {
    setLeadMessage(siteConfig.whatsapp_widget_message || "Olá! Gostaria de saber mais sobre a Evolução Clínica.");
    setIsWhatsappFormOpen(true);
    setShowWhatsappTooltip(false);
  };

  const handleSubmitLead = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!leadName.trim() || !leadPhone.trim()) return;

    setSubmittingLead(true);
    try {
      // A aquisição é capturada no primeiro acesso e pode sobreviver à limpeza
      // da URL, navegação SPA e retorno do OAuth.
      const acquisition = getCurrentAcquisitionData();
      const utmSource = acquisition.utm_source || null;
      const utmMedium = acquisition.utm_medium || null;
      const utmCampaign = acquisition.utm_campaign || null;
      const utmTerm = acquisition.utm_term || null;
      const utmContent = acquisition.utm_content || null;

      // 2. Tentar salvar o lead no banco de dados
      const { error } = await supabase
        .from('whatsapp_leads')
        .insert({
          name: leadName,
          phone: leadPhone.replace(/\D/g, ''),
          message: leadMessage,
          utm_source: utmSource,
          utm_medium: utmMedium,
          utm_campaign: utmCampaign,
          utm_term: utmTerm,
          utm_content: utmContent,
          referrer: document.referrer || null
        });

      if (error) throw error;
    } catch (err) {
      console.error("Erro ao salvar lead do WhatsApp no Supabase:", err);
      // Continuamos o redirecionamento mesmo se der erro para não travar o cliente
    } finally {
      setSubmittingLead(false);
      setIsWhatsappFormOpen(false);

      // 3. Redirecionar para o WhatsApp
      const finalPhone = (siteConfig.whatsapp_number || '').replace(/\D/g, '');
      const url = `https://wa.me/${finalPhone}?text=${encodeURIComponent(leadMessage)}`;
      window.open(url, '_blank', 'noopener,noreferrer');

      // Limpar formulário
      setLeadName('');
      setLeadPhone('');
    }
  };

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 400) {
        setShowScrollTop(true);
      } else {
        setShowScrollTop(false);
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  const [plans, setPlans] = useState<any[]>([]);
  const [activeSpecialty, setActiveSpecialty] = useState('psicologia');
  const [pacientesPorSemana, setPacientesPorSemana] = useState(20);
  const [tempoPorEvolucao, setTempoPorEvolucao] = useState(15);

  useEffect(() => {
    const fetchPlans = async () => {
      try {
        const { data, error } = await supabase
          .from('plans')
          .select('*')
          .order('price', { ascending: true });
        if (error) throw error;
        if (data && data.length > 0) {
          setPlans(data);
        }
      } catch (e) {
        console.error("Error fetching plans in landing page:", e);
      }
    };
    fetchPlans();
  }, []);

  // States for the interactive simulation
  const [simStep, setSimStep] = useState<'idle' | 'recording' | 'transcribing' | 'completed'>('idle');
  const [typedText, setTypedText] = useState('');
  const fullTranscript = "Paciente relata crises de ansiedade recorrentes na última semana, engatilhadas por prazos no trabalho. Apresenta insônia inicial de 2 horas e cefaleia tensional. Humor deprimido e afeto ansioso. Relatou melhora parcial após técnicas de respiração recomendadas na última consulta.";

  const toggleFaq = (index: number) => {
    setFaqOpen(faqOpen === index ? null : index);
  };

  const startSimulation = () => {
    if (simStep !== 'idle') return;
    setSimStep('recording');

    // Simulate recording for 2 seconds
    setTimeout(() => {
      setSimStep('transcribing');
      // Simulate typing/transcribing
      let i = 0;
      const interval = setInterval(() => {
        setTypedText(prev => prev + fullTranscript.charAt(i));
        i++;
        if (i >= fullTranscript.length) {
          clearInterval(interval);
          setSimStep('completed');
        }
      }, 15);
    }, 1500);
  };

  const resetSimulation = () => {
    setSimStep('idle');
    setTypedText('');
  };

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
    setMobileMenuOpen(false);
  };

  const faqs = [
    {
      q: "Como o aplicativo grava e transcreve os áudios?",
      a: "Você pode gravar diretamente pelo microfone do celular ou computador dentro do aplicativo ou compartilhar um arquivo de áudio gravado no WhatsApp ou no gravador do celular. Cada evolução aceita até 20 minutos no Trial e plano mensal, ou até 60 minutos no plano anual. A transcrição segue uma política de uso justo mensal de até 20 horas por profissional, com opção de contratação adicional quando necessário."
    },
    {
      q: "Como funciona a integração com o Google Drive?",
      a: "Tudo é salvo de forma totalmente transparente na sua própria conta do Google. Na primeira vez que você entra, concede permissão ao app para criar documentos e pastas no seu Google Drive. Nós criamos uma pasta organizada chamada 'Evolução Clínica' e salvamos cada prontuário lá, em formato Google Docs. Os dados são inteiramente seus."
    },
    {
      q: "Como funciona o teste gratuito de 7 dias?",
      a: "Ao criar sua conta, você recebe acesso completo por 7 dias, como se já fosse assinante. Depois desse prazo, o acesso às funcionalidades principais é bloqueado até você escolher um plano."
    },
    {
      q: "O sistema atende aos requisitos da LGPD?",
      a: "Sim, com rigor máximo. Toda a comunicação de dados é criptografada e o armazenamento dos prontuários é feito diretamente no seu próprio Google Drive pessoal ou corporativo, garantindo que terceiros não tenham acesso aos dados confidenciais dos seus pacientes."
    },
    {
      q: "Como funciona o reembolso garantido de 7 dias?",
      a: "Respeitamos integralmente o Código de Defesa do Consumidor (CDC). Se você assinar qualquer plano e decidir que a ferramenta não é adequada à sua prática nas primeiras 24 horas ou nos primeiros 7 dias, basta acessar a aba de Assinaturas e solicitar o cancelamento e estorno imediato com apenas um clique."
