            </svg>
          </button>
        </div>
      )}

      {/* Modal do Pré-formulário do WhatsApp */}
      {isWhatsappFormOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          {/* Overlay */}
