import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { supabase } from '../supabaseClient';
import { useAuthStore } from '../store/authStore';
import { PanelPageHeader } from '../components/layout/PanelPageHeader';
import { showAlert, showConfirm } from '../store/modalStore';
import { mergeNotificationSettings } from '../utils/notificationSettings';
import { 
  Bell, BellOff, CheckCheck, Trash2, Mail, Settings, Shield, 
  Info, AlertTriangle, CheckCircle2, XCircle, Loader2 
} from 'lucide-react';

interface Notification {
  id: string;
  user_id: string;
  title: string;
  message: string;
  type: 'info' | 'success' | 'warning' | 'error';
  read_at: string | null;
  link: string | null;
  image_url: string | null;
  created_at: string;
}

interface NativePushBridge {
  isAvailable?: () => boolean;
  isPermissionGranted?: () => boolean;
  requestToken?: () => void;
  refreshToken?: () => void;
  deleteToken?: () => void;
}

declare global {
  interface Window {
    NativePushBridge?: NativePushBridge;
  }
}

export default function Notifications() {
  const NATIVE_PUSH_ENABLED_KEY = 'evolucao-clinica:native-push-enabled';
  const { user, profileRole } = useAuthStore();
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [loading, setLoading] = useState(true);

  // Push states
  const [isPushSupported, setIsPushSupported] = useState(false);
  const [isNativePushApp, setIsNativePushApp] = useState(false);
  const [isPushSubscribed, setIsPushSubscribed] = useState(false);
  const [pushPermission, setPushPermission] = useState<NotificationPermission>('default');
  const [pushLoading, setPushLoading] = useState(false);

  // SMTP settings states (for admin)
  const [smtpHost, setSmtpHost] = useState('');
  const [smtpPort, setSmtpPort] = useState('587');
  const [smtpUser, setSmtpUser] = useState('');
  const [smtpPass, setSmtpPass] = useState('');
  const [smtpFrom, setSmtpFrom] = useState('');
  const [vapidPublic, setVapidPublic] = useState('');
  const [vapidPrivate, setVapidPrivate] = useState('');
  const [smtpSaving, setSmtpSaving] = useState(false);
  const [smtpSuccess, setSmtpSuccess] = useState(false);

  // Test email states
  const [testEmailTarget, setTestEmailTarget] = useState('');
  const [testEmailSending, setTestEmailSending] = useState(false);
  const [testEmailStatus, setTestEmailStatus] = useState<'success' | 'error' | null>(null);
  const [testEmailMessage, setTestEmailMessage] = useState('');

  const handleSendTestEmail = async () => {
    if (!testEmailTarget) return;
    setTestEmailSending(true);
    setTestEmailStatus(null);
    setTestEmailMessage('');

    try {
      const session = await supabase.auth.getSession();
      const token = session.data.session?.access_token;

      const res = await fetch('/api/notifications/test-email', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          toEmail: testEmailTarget,
          smtpHost: smtpHost,
          smtpPort: smtpPort,
          smtpUser: smtpUser,
          smtpPass: smtpPass,
          smtpFrom: smtpFrom
        })
      });

      const data = await res.json().catch(() => ({}));

      if (res.ok) {
        setTestEmailStatus('success');
        setTestEmailMessage('E-mail de teste enviado com sucesso!');
      } else {
        setTestEmailStatus('error');
        setTestEmailMessage(data.error || 'Erro ao enviar e-mail de teste.');
      }
    } catch (err: any) {
      setTestEmailStatus('error');
      setTestEmailMessage(err.message || 'Falha na conexão.');
    } finally {
      setTestEmailSending(false);
    }
  };

  // 1. Carregar Notificações do Banco
  const fetchNotifications = async () => {
    if (!user) return;
    try {
      const { data, error } = await supabase
        .from('notifications')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setNotifications(data || []);
    } catch (err) {
      console.error('Erro ao buscar notificacoes:', err);
    } finally {
      setLoading(false);
    }
  };

  // 2. Carregar Configurações SMTP (Apenas Admin)
  const fetchSmtpSettings = async () => {
    if (profileRole !== 'admin') return;
    try {
      const { data, error } = await supabase
        .from('settings')
        .select('api_key')
        .eq('id', 'notification_settings')
        .single();

      if (!error && data && data.api_key) {
        const parsed = JSON.parse(data.api_key);
        setSmtpHost(parsed.smtp_host || '');
        setSmtpPort(parsed.smtp_port || '587');
        setSmtpUser(parsed.smtp_user || '');
        setSmtpPass(parsed.smtp_pass || '');
        setSmtpFrom(parsed.smtp_from || '');
        setVapidPublic(parsed.vapid_public_key || '');
        setVapidPrivate(parsed.vapid_private_key || '');
      }
    } catch (err) {
      console.error('Erro ao buscar configuracoes SMTP:', err);
    }
  };

  // Checar suporte e estado de Push
  const checkPushSubscription = async () => {
    const nativePush = window.NativePushBridge;
    setIsNativePushApp(Boolean(nativePush));
    if (nativePush?.isAvailable?.()) {
      setIsPushSupported(true);
      setPushPermission(nativePush.isPermissionGranted?.() ? 'granted' : 'denied');
      const nativePushEnabled = window.localStorage.getItem(NATIVE_PUSH_ENABLED_KEY) === 'true';
      setIsPushSubscribed(nativePushEnabled && nativePush.isPermissionGranted?.() === true);
      if (nativePushEnabled && nativePush.isPermissionGranted?.()) nativePush.requestToken?.();
      return;
    }

    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
      setIsPushSupported(false);
      return;
    }
    setIsPushSupported(true);
    setPushPermission(Notification.permission);

    try {
      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.getSubscription();
      setIsPushSubscribed(!!sub);
    } catch (err) {
      console.error('Erro ao verificar inscricao de push:', err);
    }
  };

  useEffect(() => {
    if (user) {
      const handleNativePushToken = (event: Event) => {
        const token = (event as CustomEvent<{ token?: string }>).detail?.token;
        if (token) void registerNativePushToken(token);
      };
      window.addEventListener('native-push-token', handleNativePushToken);
      fetchNotifications();
      checkPushSubscription();
      fetchSmtpSettings();

      // Realtime subscription para receber novas notificacoes instantaneamente
      const channel = supabase
        .channel('realtime:notifications')
        .on(
          'postgres_changes',
          { event: '*', schema: 'public', table: 'notifications', filter: `user_id=eq.${user.id}` },
          () => {
            fetchNotifications();
          }
        )
        .subscribe();

      return () => {
        window.removeEventListener('native-push-token', handleNativePushToken);
        void supabase.removeChannel(channel);
      };
    }
  }, [user, profileRole]);

  const registerNativePushToken = async (token: string) => {
    if (!user) return;
    const session = await supabase.auth.getSession();
    const accessToken = session.data.session?.access_token;
    const res = await fetch('/api/notifications/subscribe', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${accessToken}`
      },
      body: JSON.stringify({ provider: 'fcm', token })
    });
    if (!res.ok) throw new Error('Não foi possível registrar as notificações do aplicativo.');
    window.localStorage.setItem(NATIVE_PUSH_ENABLED_KEY, 'true');
    setIsPushSubscribed(true);
  };

  // Converter string VAPID para Uint8Array
  const urlBase64ToUint8Array = (base64String: string) => {
    const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);
    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  };

  // Habilitar Notificações Push
  const subscribePush = async () => {
    if (!user) return;
    setPushLoading(true);
    try {
      const nativePush = window.NativePushBridge;
      if (nativePush?.isAvailable?.()) {
        if (!nativePush.isPermissionGranted?.()) {
          throw new Error('Permissão de notificações não concedida no Android. Ative-a nas configurações do aplicativo.');
        }

        nativePush.requestToken?.();
        await new Promise<void>((resolve, reject) => {
          const onToken = (event: Event) => {
            const token = (event as CustomEvent<{ token?: string }>).detail?.token;
            if (!token) return;
            window.clearTimeout(timeout);
            window.removeEventListener('native-push-token', onToken);
            void registerNativePushToken(token).then(resolve).catch(reject);
          };
          const timeout = window.setTimeout(() => {
            window.removeEventListener('native-push-token', onToken);
            reject(new Error('Tempo excedido ao registrar o dispositivo para notificações.'));
          }, 15000);
          window.addEventListener('native-push-token', onToken);
        });
        return;
      }

      // Solicitar permissao
      const permission = await Notification.requestPermission();
      setPushPermission(permission);

      if (permission !== 'granted') {
        throw new Error('Permissao de notificacao nao concedida.');
      }

      // Buscar VAPID public key da API do Express
      const session = await supabase.auth.getSession();
      const token = session.data.session?.access_token;

      const keyRes = await fetch('/api/notifications/vapid-public-key', {
        cache: 'no-store'
      });
      const { publicKey } = await keyRes.json();
      if (!publicKey) throw new Error('Falha ao obter chave publica VAPID do servidor.');

      const reg = await navigator.serviceWorker.ready;
      let applicationServerKey: Uint8Array;
      try {
        applicationServerKey = urlBase64ToUint8Array(String(publicKey).trim());
      } catch {
        throw new Error('Chave VAPID inválida recebida do servidor. Regrave as chaves Web Push no painel administrativo.');
      }

      // Inscrever no push manager
      let subscription;
      try {
        subscription = await reg.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey
        });
      } catch (subscribeErr: any) {
        if (subscribeErr?.name === 'AbortError') {
          throw new Error('Falha ao registrar no serviço push do navegador. Verifique as chaves Web Push/VAPID configuradas no painel administrativo.');
        }
        throw subscribeErr;
      }

      // Salvar inscricao no backend Express
      const res = await fetch('/api/notifications/subscribe', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ subscription })
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Erro ao registrar inscricao no servidor.');
      }

      setIsPushSubscribed(true);
    } catch (err: any) {
      console.error('Erro ao ativar push:', err);
      await showAlert(err.message || 'Erro ao ativar notificações push.', {
        title: "Erro no Push",
        variant: "danger",
        icon: "warning"
      });
    } finally {
      setPushLoading(false);
    }
  };

  // Desativar Notificações Push
  const unsubscribePush = async () => {
    if (!user) return;
    setPushLoading(true);
    try {
      const nativePush = window.NativePushBridge;
      if (nativePush?.isAvailable?.()) {
        const session = await supabase.auth.getSession();
        const accessToken = session.data.session?.access_token;
        await fetch('/api/notifications/unsubscribe', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${accessToken}`
          },
          body: JSON.stringify({ provider: 'fcm' })
        });
        nativePush.deleteToken?.();
        window.localStorage.removeItem(NATIVE_PUSH_ENABLED_KEY);
        setIsPushSubscribed(false);
        return;
      }

      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.getSubscription();

      if (sub) {
        const session = await supabase.auth.getSession();
        const token = session.data.session?.access_token;

        // Remover no servidor Express
        await fetch('/api/notifications/unsubscribe', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify({ endpoint: sub.endpoint })
        });

        // Cancelar inscricao no navegador
        await sub.unsubscribe();
      }

      setIsPushSubscribed(false);
    } catch (err: any) {
      console.error('Erro ao desativar push:', err);
      await showAlert('Erro ao desativar notificações push.', {
        title: "Erro no Push",
        variant: "danger",
        icon: "warning"
      });
    } finally {
      setPushLoading(false);
    }
  };

  // 6. Marcar Notificação específica como lida
  const markAsRead = async (id: string) => {
    try {
      const { error } = await supabase
        .from('notifications')
        .update({ read_at: new Date().toISOString() })
        .eq('id', id);

      if (error) throw error;
      setNotifications(prev => 
        prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n)
      );
    } catch (err) {
      console.error('Erro ao marcar como lida:', err);
    }
  };

  // 7. Marcar todas como lidas
  const markAllAsRead = async () => {
    try {
      const { error } = await supabase
        .from('notifications')
        .update({ read_at: new Date().toISOString() })
        .eq('user_id', user?.id)
        .is('read_at', null);

      if (error) throw error;
      setNotifications(prev => prev.map(n => ({ ...n, read_at: n.read_at || new Date().toISOString() })));
    } catch (err) {
      console.error('Erro ao marcar todas como lidas:', err);
    }
  };

  // 8. Limpar todas as notificações
  const clearAllNotifications = async () => {
    const confirmed = await showConfirm('Deseja realmente excluir todas as suas notificações?', {
      title: "Excluir Notificações",
      confirmLabel: "Excluir Tudo",
      cancelLabel: "Cancelar",
      variant: "danger",
      icon: "trash"
    });
    if (!confirmed) return;
    try {
      const { error } = await supabase
        .from('notifications')
        .delete()
        .eq('user_id', user?.id);

      if (error) throw error;
      setNotifications([]);
    } catch (err) {
      console.error('Erro ao excluir notificações:', err);
    }
  };

  // 9. Salvar Configurações SMTP (Admin)
  const saveSmtpSettings = async (e: React.FormEvent) => {
    e.preventDefault();
    setSmtpSaving(true);
    setSmtpSuccess(false);

    try {
      const settings = {
        smtp_host: smtpHost,
        smtp_port: smtpPort,
        smtp_user: smtpUser,
        smtp_pass: smtpPass,
        smtp_from: smtpFrom,
        vapid_public_key: vapidPublic,
        vapid_private_key: vapidPrivate,
        vapid_subject: `mailto:${smtpUser || 'contato@evolucaoclinica.app.br'}`
      };

      const { data: currentSettings } = await supabase
        .from('settings')
        .select('api_key')
        .eq('id', 'notification_settings')
        .maybeSingle();
      let currentSettingsJson: Record<string, unknown> = {};
      if (currentSettings?.api_key) {
        try {
          currentSettingsJson = JSON.parse(currentSettings.api_key);
        } catch (parseError) {
          console.error('Erro ao ler configurações atuais de notificações:', parseError);
        }
      }

      const { error } = await supabase
        .from('settings')
        .upsert({
          id: 'notification_settings',
          api_key: JSON.stringify(mergeNotificationSettings(currentSettingsJson, settings)),
          updated_at: new Date().toISOString(),
          updated_by: user?.email || 'admin'
        });

      if (error) throw error;
      setSmtpSuccess(true);
      setTimeout(() => setSmtpSuccess(false), 3000);
    } catch (err) {
      console.error('Erro ao salvar configuracoes SMTP:', err);
      await showAlert('Erro ao salvar configurações do servidor.', {
        title: "Erro ao Salvar",
        variant: "danger",
        icon: "warning"
      });
    } finally {
      setSmtpSaving(false);
    }
  };

  // A função de enviar notificação de teste geral foi removida (o SMTP ainda possui teste de e-mail SMTP individual no formulário do administrador).

  // Formatar data
  const formatDate = (dateString: string) => {
    const d = new Date(dateString);
    return d.toLocaleString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  // Unread count
  const unreadCount = notifications.filter(n => !n.read_at).length;

  return (
    <div className="space-y-8 animate-fade-in pb-12">
      <PanelPageHeader
        icon={Bell}
        title="Central de Notificações"
        description="Gerencie seus alertas na plataforma, notificações push e configurações de e-mail."
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Lado Esquerdo: Lista de Notificações In-App (2/3 de largura no desktop) */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-2xl border border-brand-border/60 shadow-sm p-6">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-brand-border/40 pb-4 mb-6">
              <div className="flex items-center space-x-2">
                <Bell className="text-brand-primary w-5 h-5" />
                <h2 className="text-lg font-semibold text-brand-text">Notificações Recentes</h2>
                {unreadCount > 0 && (
                  <span className="bg-brand-primary text-white text-xs font-semibold px-2 py-0.5 rounded-full">
                    {unreadCount} não {unreadCount === 1 ? 'lida' : 'lidas'}
                  </span>
                )}
              </div>

              {notifications.length > 0 && (
                <div className="flex items-center gap-3">
                  <button 
                    onClick={markAllAsRead}
                    disabled={unreadCount === 0}
                    className="flex items-center space-x-1.5 text-sm text-brand-primary hover:text-brand-primary-dark font-medium disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                  >
                    <CheckCheck size={16} />
                    <span>Ler todas</span>
                  </button>
                  <span className="text-brand-border/40">|</span>
                  <button 
                    onClick={clearAllNotifications}
                    className="flex items-center space-x-1.5 text-sm text-red-600 hover:text-red-700 font-medium transition-colors"
                  >
                    <Trash2 size={16} />
                    <span>Limpar histórico</span>
                  </button>
                </div>
              )}
            </div>

            {loading ? (
              <div className="flex flex-col items-center justify-center py-16 space-y-3">
                <Loader2 className="w-8 h-8 text-brand-primary animate-spin" />
                <p className="text-brand-text-muted text-sm">Carregando notificações...</p>
              </div>
            ) : notifications.length === 0 ? (
              <div className="text-center py-16 space-y-4">
                <div className="w-16 h-16 bg-brand-bg rounded-full flex items-center justify-center mx-auto text-brand-text-muted">
                  <BellOff size={28} />
                </div>
                <div className="max-w-xs mx-auto">
                  <h3 className="font-semibold text-brand-text">Nenhuma notificação por aqui</h3>
                  <p className="text-sm text-brand-text-muted mt-1">Você está em dia com seus prontuários e alertas do sistema!</p>
                </div>
              </div>
            ) : (
              <div className="flex flex-col gap-3.5 max-h-[550px] overflow-y-auto pr-1">
                {notifications.map((item) => {
                  const Icon = 
                    item.type === 'success' ? CheckCircle2 :
                    item.type === 'error' ? XCircle :
                    item.type === 'warning' ? AlertTriangle : Info;

                  const colorClass = 
                    item.type === 'success' ? 'text-emerald-500 bg-emerald-50 border-emerald-100' :
                    item.type === 'error' ? 'text-red-500 bg-red-50 border-red-100' :
                    item.type === 'warning' ? 'text-amber-500 bg-amber-50 border-amber-100' :
                    'text-brand-primary bg-brand-bg border-brand-border';

                  return (
                    <div 
                      key={item.id} 
                      onClick={() => !item.read_at && markAsRead(item.id)}
                      className={`py-4 px-4 flex gap-4 items-start transition-all rounded-xl hover:bg-brand-bg/30 cursor-pointer border shadow-sm ${!item.read_at ? 'bg-brand-primary/5 border-brand-primary/20 border-l-4 border-l-brand-primary' : 'bg-white border-brand-border/50'}`}
                    >
                      <div className={`p-2 rounded-lg border flex-shrink-0 ${colorClass}`}>
                        <Icon size={18} />
                      </div>

                      <div className="min-w-0 flex-1 space-y-3">
                        {item.image_url && (
                          <div className="w-full overflow-hidden rounded-xl border border-brand-border/40 shadow-sm bg-brand-bg/20">
                            <img
                              src={item.image_url}
                              alt="Capa da notificação"
                              referrerPolicy="no-referrer"
                              loading="eager"
                              className="block w-full h-auto object-contain"
                            />
                          </div>
                        )}

                        <div className="flex items-start justify-between gap-2">
                          <p className={`min-w-0 flex-1 text-sm font-semibold leading-snug break-words ${!item.read_at ? 'text-brand-primary font-bold' : 'text-brand-text'}`}>
                            {item.title}
                          </p>
                          <span className="text-[10px] text-brand-text-muted flex-shrink-0 whitespace-nowrap pt-0.5">{formatDate(item.created_at)}</span>
                        </div>
                        <p className="text-sm text-brand-text-muted leading-relaxed break-words whitespace-pre-line md:line-clamp-2">
                          {item.message}
                        </p>

                        {item.link && (
                          <a 
                            href={item.link} 
                            onClick={(e) => e.stopPropagation()} 
                            className="inline-block text-xs font-semibold text-brand-primary hover:underline mt-2.5"
                          >
                            Ver detalhes &rarr;
                          </a>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Lado Direito: Controles Push & SMTP Admin (1/3 de largura) */}
        <div className="space-y-6">

          {/* Caixa de Configurações Push do Usuário */}
          <div className="bg-white rounded-2xl border border-brand-border/60 shadow-sm p-6 space-y-5">
            <h3 className="text-lg font-semibold text-brand-text flex items-center space-x-2">
              <Bell className="text-brand-primary w-5 h-5" />
              <span>{isNativePushApp ? 'Notificações do Aplicativo' : 'Notificações no Navegador'}</span>
            </h3>

            {!isPushSupported ? (
              <div className="bg-amber-50 border border-amber-100 p-4 rounded-xl flex gap-3 text-amber-800">
                <AlertTriangle className="flex-shrink-0 mt-0.5" size={18} />
                <div className="text-xs space-y-1">
                  <p className="font-semibold">{isNativePushApp ? 'Notificações nativas indisponíveis' : 'Navegador não suportado'}</p>
                  <p>{isNativePushApp
                    ? 'Atualize o aplicativo para ativar as notificações nativas pelo Firebase.'
                    : 'Seu navegador atual ou modo de navegação privada não possui suporte a notificações push nativas.'}</p>
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="flex items-center justify-between bg-brand-bg/50 p-4 rounded-xl border border-brand-border/40">
                  <div>
                    <p className="text-xs font-semibold text-brand-text">{isNativePushApp ? 'Status do aplicativo' : 'Status do navegador'}</p>
                    <p className="text-xs text-brand-text-muted mt-0.5">
                      {pushPermission === 'granted' ? 'Permitido ✅' :
                       pushPermission === 'denied' ? 'Bloqueado ❌' : 'Não Solicitado 🔔'}
                    </p>
                  </div>

                  {pushPermission === 'denied' && (
                    <span className="text-[10px] text-red-600 bg-red-50 px-2 py-1 rounded font-medium border border-red-100">Desbloqueie no cadeado</span>
                  )}
                </div>

                <div className="space-y-3">
                  {isPushSubscribed ? (
                    <button
                      onClick={unsubscribePush}
                      disabled={pushLoading}
                      className="w-full flex items-center justify-center space-x-2 px-4 py-2.5 rounded-xl border border-red-200 text-red-600 hover:bg-red-50 font-medium transition-colors text-sm disabled:opacity-50"
                    >
                      {pushLoading ? <Loader2 className="animate-spin" size={18} /> : <BellOff size={18} />}
                      <span>Desativar Notificações Push</span>
                    </button>
                  ) : (
                    <button
                      onClick={subscribePush}
                      disabled={pushLoading || pushPermission === 'denied'}
                      className="w-full flex items-center justify-center space-x-2 px-4 py-2.5 rounded-xl bg-brand-primary text-white hover:bg-brand-primary-dark font-medium transition-colors text-sm disabled:opacity-50"
                    >
                      {pushLoading ? <Loader2 className="animate-spin" size={18} /> : <Bell size={18} />}
                      <span>Ativar Notificações Push</span>
                    </button>
                  )}

                  <p className="text-[10px] text-brand-text-muted leading-relaxed text-center">
                    Permite receber notificações do app diretamente na área de trabalho ou tela de bloqueio do celular, mesmo que o navegador esteja fechado.
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* Caixa de Preferências de Comunicação */}
          <div className="bg-white rounded-2xl border border-brand-border/60 shadow-sm p-6 space-y-4">
            <h3 className="text-lg font-semibold text-brand-text flex items-center space-x-2">
              <Mail className="text-brand-primary w-5 h-5" />
              <span>Preferências de Comunicação</span>
            </h3>
            <p className="text-xs text-brand-text-muted leading-relaxed">
              Gerencie quais e-mails, alertas e mensagens de WhatsApp você deseja receber da plataforma, além de configurar notificações push nativas no seu navegador.
            </p>
            <Link
              to="/painel/preferencias-de-comunicacao"
              className="w-full flex items-center justify-center space-x-2 px-4 py-2.5 rounded-xl bg-brand-primary text-white hover:bg-brand-primary-dark font-semibold text-sm transition-all"
            >
              <span>Gerenciar Preferências</span>
            </Link>
          </div>

          {/* Configurações de SMTP para Administrador */}
          {profileRole === 'admin' && (
            <form onSubmit={saveSmtpSettings} className="bg-white rounded-2xl border border-brand-border/60 shadow-sm p-6 space-y-4">
              <h3 className="text-lg font-semibold text-brand-text flex items-center space-x-2">
                <Settings className="text-brand-primary w-5 h-5" />
                <span>Configurar Servidor SMTP</span>
              </h3>

              <p className="text-xs text-brand-text-muted">
                (Apenas Administradores) Defina os dados de conexão SMTP para que a plataforma envie e-mails de notificação aos profissionais.
              </p>

              <div className="space-y-3">
                <div>
                  <label className="text-[10px] font-bold text-brand-text block mb-1">HOST SMTP</label>
                  <input
                    type="text"
                    value={smtpHost}
                    onChange={e => setSmtpHost(e.target.value)}
                    placeholder="ex: smtp.gmail.com"
                    required
                    className="w-full text-sm border border-brand-border/80 rounded-xl px-3 py-2 bg-brand-bg/30 focus:outline-none focus:border-brand-primary focus:bg-white transition-all"
                  />
                </div>

                <div className="grid grid-cols-3 gap-2">
                  <div className="col-span-2">
                    <label className="text-[10px] font-bold text-brand-text block mb-1">USUÁRIO SMTP</label>
                    <input
                      type="text"
                      value={smtpUser}
                      onChange={e => setSmtpUser(e.target.value)}
                      placeholder="seu-email@dominio.com"
                      required
                      className="w-full text-sm border border-brand-border/80 rounded-xl px-3 py-2 bg-brand-bg/30 focus:outline-none focus:border-brand-primary focus:bg-white transition-all"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-brand-text block mb-1">PORTA</label>
                    <input
                      type="text"
                      value={smtpPort}
                      onChange={e => setSmtpPort(e.target.value)}
                      placeholder="587"
                      required
                      className="w-full text-sm border border-brand-border/80 rounded-xl px-3 py-2 bg-brand-bg/30 focus:outline-none focus:border-brand-primary focus:bg-white transition-all"
                    />
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-bold text-brand-text block mb-1">SENHA SMTP</label>
                  <input
                    type="password"
                    value={smtpPass}
                    onChange={e => setSmtpPass(e.target.value)}
                    placeholder="Sua senha do servidor"
                    required
                    className="w-full text-sm border border-brand-border/80 rounded-xl px-3 py-2 bg-brand-bg/30 focus:outline-none focus:border-brand-primary focus:bg-white transition-all"
                  />
                </div>

                <div>
                  <label className="text-[10px] font-bold text-brand-text block mb-1">E-MAIL REMETENTE (FROM)</label>
                  <input
                    type="text"
                    value={smtpFrom}
                    onChange={e => setSmtpFrom(e.target.value)}
                    placeholder='"Suporte Ser" <email@dominio.com>'
                    className="w-full text-sm border border-brand-border/80 rounded-xl px-3 py-2 bg-brand-bg/30 focus:outline-none focus:border-brand-primary focus:bg-white transition-all"
                  />
