import React, { useEffect, useState, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Calendar, CheckCircle2, FileText, Mic, Sparkles, Users, ArrowRight, RefreshCw, Loader2, ShieldCheck, ChevronRight, ChevronLeft, ChevronDown, Volume2, Award, Compass, ListChecks, MessageCircle, RotateCcw, LogOut } from 'lucide-react';
import { supabase } from '../supabaseClient';
import { useAuthStore } from '../store/authStore';
import { useSiteConfig } from '../hooks/useSiteConfig';
import { appendBrandAssetVersion, getBrandAssetSignature } from '../utils/brandAssets';
import { chooseOnboardingMode, completeOnboarding, deferOnboarding, ensureOnboardingState, getOnboardingDestination, setOnboardingState } from '../utils/onboarding';
import { classifyOnboardingError, isOnboardingChoiceRequired } from '../utils/onboardingState';
import { listGoogleCalendarEvents } from '../services/googleCalendar';
import { GoogleSecurityModal } from '../components/common/GoogleSecurityModal';
import { GOOGLE_SCOPE_SETS, hasGoogleScopes, requestGoogleOAuth } from '../services/googleAuth';
import { trackEvent } from '../services/analytics';
import { trackLifecycleEvent } from '../services/lifecycleTelemetry';
import {
  DEFAULT_WHATSAPP_COUNTRY,
  formatWhatsAppNationalNumber,
  getWhatsAppCountryCallingCode,
  getWhatsAppCountryOptions,
  normalizeRequiredWhatsAppNationalNumber,
  splitStoredWhatsAppNumber,
  type CountryCode,
} from '../utils/whatsappNumber';

const WHATSAPP_COUNTRY_OPTIONS = getWhatsAppCountryOptions();

const normalizeText = (text: string): string => {
  if (!text) return '';
  return text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
};

const matchPatientWithEvent = (patient: any, summary: string, description: string): boolean => {
  const normSummary = normalizeText(summary);
  const normDesc = normalizeText(description);
  const normFullName = normalizeText(patient.full_name || '');

  if (normFullName && (normSummary.includes(normFullName) || normDesc.includes(normFullName))) {
    return true;
  }

  const ignoreWords = ['de', 'da', 'do', 'das', 'dos', 'com', 'para', 'em'];
  const nameParts = normFullName.split(/\s+/).filter((part) => part.length >= 2 && !ignoreWords.includes(part));

  if (nameParts.length > 0) {
    const firstName = nameParts[0];
    const firstRegex = new RegExp(`\\b${firstName}\\b`, 'i');
    if (firstRegex.test(normSummary) || firstRegex.test(normDesc)) {
      return true;
    }

    if (firstName.length >= 4 && (normSummary.includes(firstName) || normDesc.includes(firstName))) {
      return true;
    }

    for (let i = 1; i < nameParts.length; i += 1) {
      const part = nameParts[i];
      const partRegex = new RegExp(`\\b${part}\\b`, 'i');
      if (partRegex.test(normSummary) || partRegex.test(normDesc)) {
        return true;
      }

      if (part.length >= 4 && (normSummary.includes(part) || normDesc.includes(part))) {
        return true;
      }
    }
  }

  return false;
};

type AgendaSyncSummary = {
  patientsCount: number;
  evolutionsCount: number;
  matchedEventsCount: number;
  syncedAt: string;
};

type WhatsAppOtpRequest = {
  requestId: string;
  maskedPhone: string;
  resendAvailableAt: number;
};

export default function Onboarding() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { user, googleAccessToken, googleGrantedScopes, setGoogleAccessToken, isAuthReady } = useAuthStore();
  const siteConfig = useSiteConfig();
  const assetSignature = getBrandAssetSignature(siteConfig);
  const [syncingAgenda, setSyncingAgenda] = useState(false);
  const [syncError, setSyncError] = useState('');
  const [syncSummary, setSyncSummary] = useState<AgendaSyncSummary | null>(null);
  const [isSecurityModalOpen, setIsSecurityModalOpen] = useState(false);
  const [whatsappCountry, setWhatsappCountry] = useState<CountryCode>(DEFAULT_WHATSAPP_COUNTRY);
  const [whatsappNumber, setWhatsappNumber] = useState('');
  const [whatsappError, setWhatsappError] = useState('');
  const [savingWhatsapp, setSavingWhatsapp] = useState(false);
  const [verifyingWhatsapp, setVerifyingWhatsapp] = useState(false);
  const [whatsappOtpRequest, setWhatsappOtpRequest] = useState<WhatsAppOtpRequest | null>(null);
  const [whatsappOtpCode, setWhatsappOtpCode] = useState('');
  const [whatsappResendSeconds, setWhatsappResendSeconds] = useState(0);
  const [exitingOnboarding, setExitingOnboarding] = useState(false);
  const [exitError, setExitError] = useState('');
  const [choosingMode, setChoosingMode] = useState<'guided' | 'explore' | null>(null);
  const [choiceError, setChoiceError] = useState('');

  // Controle local do Slider de Apresentação (passo 'intro')
  const [activeSlide, setActiveSlide] = useState(0);

  // Referências para capturar gestos de swipe (toque)
  const touchStartX = useRef(0);
  const touchEndX = useRef(0);

  const onboardingState = user?.id ? ensureOnboardingState(user.id) : null;
  const showStartChoice = isOnboardingChoiceRequired(onboardingState);
  const activeStep = (searchParams.get('step') as 'intro' | 'agenda' | 'complete' | null) || onboardingState?.step || 'intro';
  const isAgendaStep = activeStep === 'agenda';
  const agendaAlreadySynced = Boolean(onboardingState?.agendaSyncedAt);
  const isCompleteStep = activeStep === 'complete';
  const showAgendaPendingStep = isAgendaStep && !agendaAlreadySynced && !syncSummary;
  const showCompletionStep = isCompleteStep || (isAgendaStep && (agendaAlreadySynced || syncSummary));
  const hasCalendarAccess = Boolean(googleAccessToken) && hasGoogleScopes(googleGrantedScopes, GOOGLE_SCOPE_SETS.calendarReadOnly);

  useEffect(() => {
    if (!isAuthReady) return;
    if (!user) {
      navigate('/login', { replace: true });
      return;
    }
    if (showStartChoice) return;

    if (onboardingState?.step === 'complete') {
      navigate('/painel/dashboard', { replace: true });
      return;
    }

    if (onboardingState?.step === 'patient' || onboardingState?.step === 'evolution') {
      const destination = getOnboardingDestination(user.id);
      if (destination !== '/onboarding') {
        navigate(destination, { replace: true });
      }
    }
  }, [isAuthReady, navigate, onboardingState?.step, showStartChoice, user]);

  useEffect(() => {
    if (user?.id && !onboardingState) {
      ensureOnboardingState(user.id);
    }
  }, [onboardingState, user?.id]);

  useEffect(() => {
    if (!user?.id) return;
    if (showStartChoice) return;
    let active = true;
    const loadWhatsApp = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        const token = sessionData.session?.access_token;
        if (!token) return;
        const response = await fetch('/api/communication/preferences', {
          cache: 'no-store',
          headers: { Authorization: `Bearer ${token}` }
        });
        if (!response.ok) return;
        const payload = await response.json();
        if (active && payload.preferences?.whatsapp_number) {
          const storedWhatsApp = splitStoredWhatsAppNumber(payload.preferences.whatsapp_number);
          setWhatsappCountry(storedWhatsApp.country);
          setWhatsappNumber(storedWhatsApp.nationalNumber);
        }
      } catch (error) {
        console.warn('[Onboarding] Não foi possível carregar o WhatsApp cadastrado.', error);
      }
    };
    void loadWhatsApp();
    return () => { active = false; };
  }, [user?.id]);

  useEffect(() => {
    if (!whatsappOtpRequest) {
      setWhatsappResendSeconds(0);
      return;
    }

    const updateCountdown = () => {
      setWhatsappResendSeconds(Math.max(0, Math.ceil((whatsappOtpRequest.resendAvailableAt - Date.now()) / 1000)));
    };
    updateCountdown();
    const interval = window.setInterval(updateCountdown, 1000);
    return () => window.clearInterval(interval);
  }, [whatsappOtpRequest]);

  useEffect(() => {
    if (!user?.id) return;

    if (activeStep === 'agenda') {
      setOnboardingState(user.id, { step: 'agenda' });
    } else if (activeStep === 'intro' && onboardingState?.step !== 'intro') {
      setOnboardingState(user.id, { step: 'intro' });
    }
  }, [activeStep, onboardingState?.step, showStartChoice, user?.id]);

  const finishWhatsAppStep = (normalizedWhatsApp: string) => {
    if (!user?.id) return;
    const storedWhatsApp = splitStoredWhatsAppNumber(normalizedWhatsApp);
    setWhatsappCountry(storedWhatsApp.country);
    setWhatsappNumber(storedWhatsApp.nationalNumber);
    setOnboardingState(user.id, { step: 'patient' });
    void trackLifecycleEvent('onboarding_step_completed', {
      metadata: { step: 'intro', mode: onboardingState?.mode || 'guided' },
      dedupeKey: `onboarding_step_completed:${user.id}:intro`,
    });
    trackEvent('onboarding_begin', {}, { dedupeKey: `onboarding_begin:${user.id}`, persistDedupe: true });
    navigate('/painel/patients/new?onboarding=1', { replace: true });
  };

  const requestWhatsAppOtp = async () => {
    if (!user?.id) return;
    setWhatsappError('');

    try {
      const normalizedWhatsApp = normalizeRequiredWhatsAppNationalNumber(whatsappNumber, whatsappCountry);
      setSavingWhatsapp(true);
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData.session?.access_token;
      if (!token) throw new Error('Sua sessão não está disponível. Faça login novamente.');

      const response = await fetch('/api/onboarding/whatsapp-verification/request', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ phoneNumber: normalizedWhatsApp })
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error || 'Não foi possível enviar o código pelo WhatsApp.');

      if (payload.alreadyVerified === true) {
        finishWhatsAppStep(normalizedWhatsApp);
        return;
      }
      if (!payload.requestId) throw new Error('A solicitação do código não foi identificada. Tente novamente.');
      setWhatsappOtpCode('');
      setWhatsappOtpRequest({
        requestId: String(payload.requestId),
        maskedPhone: String(payload.maskedPhone || normalizedWhatsApp),
        resendAvailableAt: Date.now() + (Number(payload.resendAfterSeconds) || 60) * 1000,
      });
    } catch (error: any) {
      setActiveSlide(3);
      setWhatsappError(error.message || 'Não foi possível enviar o código pelo WhatsApp.');
    } finally {
      setSavingWhatsapp(false);
    }
  };

  const handleVerifyWhatsAppOtp = async () => {
    if (!user?.id || !whatsappOtpRequest) return;
    setWhatsappError('');
    const code = whatsappOtpCode.replace(/\D/g, '').slice(0, 6);
    if (code.length !== 6) {
      setWhatsappError('Informe o código de 6 dígitos enviado pelo WhatsApp.');
      return;
    }

    try {
      setVerifyingWhatsapp(true);
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData.session?.access_token;
      if (!token) throw new Error('Sua sessão não está disponível. Faça login novamente.');
      const response = await fetch('/api/onboarding/whatsapp-verification/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ requestId: whatsappOtpRequest.requestId, code }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error || 'Não foi possível confirmar o código.');
      finishWhatsAppStep(String(payload.phoneNumber || normalizeRequiredWhatsAppNationalNumber(whatsappNumber, whatsappCountry)));
    } catch (error: any) {
      setWhatsappError(error.message || 'Não foi possível confirmar o código.');
    } finally {
      setVerifyingWhatsapp(false);
    }
  };

  const handleChangeWhatsAppNumber = () => {
    setWhatsappOtpRequest(null);
    setWhatsappOtpCode('');
    setWhatsappError('');
  };

  const handleChooseStartMode = async (mode: 'guided' | 'explore') => {
    if (!user?.id) return;
    setChoosingMode(mode);
    setChoiceError('');
    try {
      await chooseOnboardingMode(user.id, mode);
      if (mode === 'explore') {
        navigate('/painel/dashboard', { replace: true });
      } else {
        setActiveSlide(0);
      }
    } catch (error) {
      console.error('[Onboarding] Não foi possível salvar a escolha inicial:', error);
      setChoiceError('Não foi possível salvar sua escolha. Verifique a conexão e tente novamente.');
    } finally {
      setChoosingMode(null);
    }
  };

  const handleSkipPresentation = () => {
    if (activeStep !== 'intro' || activeSlide >= 3) return;

    // O botão pula somente os slides informativos e leva o profissional
    // diretamente ao passo prático, onde o WhatsApp é confirmado.
    setWhatsappError('');
    setActiveSlide(3);
  };

  const handleExitOnboarding = async () => {
    if (!user?.id || exitingOnboarding) return;

    setExitError('');
    setExitingOnboarding(true);
    try {
      await deferOnboarding(user.id, 'intro');
      navigate('/painel/dashboard', { replace: true });
    } catch (error) {
      console.error('[Onboarding] Não foi possível sair do onboarding:', error);
      setExitError('Não foi possível sair agora. Verifique sua conexão e tente novamente.');
    } finally {
      setExitingOnboarding(false);
    }
  };

  const handleConnectGoogleCalendar = async () => {
    setIsSecurityModalOpen(true);
  };

  const executeGoogleConnection = async () => {
    try {
      const { error } = await requestGoogleOAuth({
        requiredScopes: 'calendarReadOnly',
        currentGrantedScopes: googleGrantedScopes,
        redirectTo: window.location.origin + '/onboarding?step=agenda',
        prompt: 'consent',
        loginHint: user?.email || undefined
      });
      if (error) throw error;
    } catch (error) {
      console.error('Erro ao conectar Google Agenda:', error);
      alert('Erro ao iniciar conexão com o Google.');
    }
  };

  const handleSyncAgenda = async () => {
    if (!user?.id) return;
    if (!hasCalendarAccess) {
      alert('Sua sessão do Google precisa ser renovada antes de sincronizar a agenda.');
      return;
    }

    setSyncingAgenda(true);
    setSyncError('');

    try {
      const { data: patientsData, error: patientsError } = await supabase
        .from('patients')
        .select('id, full_name, birth_date, phone')
        .eq('professional_id', user.id)
        .eq('status', 'active');

      if (patientsError) throw patientsError;

      const now = new Date();
      const currentDay = now.getDay();
      const distanceToMonday = currentDay === 0 ? 6 : currentDay - 1;
      const startOfWeek = new Date(now.getFullYear(), now.getMonth(), now.getDate() - distanceToMonday, 0, 0, 0);

      const tomorrow = new Date();
      tomorrow.setDate(now.getDate() + 1);
      const endOfTomorrow = new Date(tomorrow.getFullYear(), tomorrow.getMonth(), tomorrow.getDate(), 23, 59, 59, 999);

      const formatDateStr = (date: Date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
      };

      const startOfWeekStr = formatDateStr(startOfWeek);
      const localTomorrowStr = formatDateStr(tomorrow);

      const { data: evolutionsThisWeek, error: evolutionsError } = await supabase
        .from('evolutions')
        .select('id, patient_id, session_date')
        .eq('professional_id', user.id)
        .gte('session_date', startOfWeekStr)
        .lte('session_date', localTomorrowStr);

      if (evolutionsError) throw evolutionsError;

      const events = await listGoogleCalendarEvents(
        googleAccessToken,
        startOfWeek.toISOString(),
        endOfTomorrow.toISOString()
      );

      const matchedEvents = events.filter((event) => {
        return (patientsData || []).some((patient) =>
          matchPatientWithEvent(patient, event.summary || '', event.description || '')
        );
      });

      setSyncSummary({
        patientsCount: patientsData?.length || 0,
        evolutionsCount: evolutionsThisWeek?.length || 0,
        matchedEventsCount: matchedEvents.length,
        syncedAt: new Date().toISOString()
      });

      if (user.id) {
        setOnboardingState(user.id, {
          step: 'agenda',
          agendaSyncedAt: new Date().toISOString()
        });
        void trackLifecycleEvent('onboarding_step_completed', {
          metadata: { step: 'agenda', mode: onboardingState?.mode || 'guided', result: 'calendar_synced' },
          dedupeKey: `onboarding_step_completed:${user.id}:agenda`,
        });
      }
    } catch (error: any) {
      console.error('Erro ao sincronizar agenda no onboarding:', error);
      void trackLifecycleEvent('onboarding_step_error', {
        metadata: {
          step: 'agenda',
          source: 'google_calendar',
          error_code: classifyOnboardingError(error, 'calendar_sync_failed'),
        },
        dedupeKey: `onboarding_step_error:${user.id}:agenda:${classifyOnboardingError(error, 'calendar_sync_failed')}:${new Date().toISOString().slice(0, 10)}`,
      });
      const message = error?.message || 'Não foi possível sincronizar a agenda.';
      if (message.includes('INSUFFICIENT_SCOPES')) {
        setSyncError('A conta Google foi conectada, mas este token ainda não tem permissão para ler a agenda. Reconecte e aprove o acesso ao Google Agenda.');
      } else if (message.includes('401') || message.includes('UNAUTHENTICATED') || message.includes('Invalid Credentials')) {
        setGoogleAccessToken(null);
        setSyncError(message);
      } else {
        setSyncError(message);
      }
    } finally {
      setSyncingAgenda(false);
    }
  };

  const handleFinish = async () => {
    if (!user?.id) return;
    const { error } = await supabase
      .from('professionals')
      .update({
        onboarding_completed: true,
        onboarding_status: 'completed',
        onboarding_current_step: 'complete',
        updated_at: new Date().toISOString(),
      })
      .eq('id', user.id);
    if (error) {
      console.error('[Onboarding] Não foi possível confirmar a conclusão no banco:', error);
      return;
    }
    completeOnboarding(user.id);
    void trackLifecycleEvent('onboarding_step_completed', {
      metadata: { step: 'complete', mode: onboardingState?.mode || 'guided' },
      dedupeKey: `onboarding_step_completed:${user.id}:complete`,
    });
    trackEvent('onboarding_complete', {}, { dedupeKey: `onboarding_complete:${user.id}`, persistDedupe: true });
    navigate('/painel/dashboard', { replace: true });
  };

  // Funções para controle de toque (swipe)
  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
    touchEndX.current = e.touches[0].clientX;
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = () => {
    const diff = touchStartX.current - touchEndX.current;
    if (diff > 50) {
      // Swipe para a esquerda -> Próximo Slide (apenas se for intro)
      if (activeStep === 'intro' && activeSlide < 3) {
        setActiveSlide((prev) => prev + 1);
      }
    } else if (diff < -50) {
      // Swipe para a direita -> Slide Anterior
      if (activeStep === 'intro' && activeSlide > 0) {
        setActiveSlide((prev) => prev - 1);
      }
    }
  };

  // Determinar qual é o status de cada etapa para a barra lateral do desktop
  const getStepStatus = (stepName: 'intro' | 'patient' | 'evolution' | 'agenda' | 'complete') => {
    const currentStepOrder = {
      intro: 0,
      patient: 1,
      evolution: 2,
      agenda: 3,
      complete: 4
    };

    const userCurrentStep = onboardingState?.step || 'intro';
    const userStepIndex = currentStepOrder[userCurrentStep];
    const targetStepIndex = currentStepOrder[stepName];

    // Lógica especial para 'agenda' e 'complete'
    if (stepName === 'agenda' && (agendaAlreadySynced || syncSummary)) {
      return 'completed';
    }

    if (userStepIndex > targetStepIndex) {
      return 'completed';
    } else if (userStepIndex === targetStepIndex) {
      // Se estamos na rota de agenda, mas o activeStep é 'agenda'
      if (stepName === 'agenda' && activeStep === 'agenda') return 'current';
      if (stepName === 'complete' && activeStep === 'complete') return 'current';
      if (stepName === 'intro' && activeStep === 'intro') return 'current';
      return 'completed';
    } else {
      return 'pending';
    }
  };

  if (showStartChoice) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-brand-bg via-white to-brand-primary/5 px-4 py-6 sm:flex sm:items-center sm:justify-center">
        <div className="mx-auto w-full max-w-4xl overflow-hidden rounded-[28px] border border-brand-border/70 bg-white shadow-2xl shadow-brand-primary/10">
          <div className="border-b border-brand-border/60 bg-gradient-to-r from-brand-primary/10 via-white to-brand-accent/10 px-6 py-7 text-center sm:px-10 sm:py-9">
            <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-primary text-white shadow-lg shadow-brand-primary/20">
              <Compass size={24} />
            </div>
            <p className="mb-2 text-[11px] font-bold uppercase tracking-[0.2em] text-brand-primary">Bem-vindo ao Evolução Clínica</p>
            <h1 className="font-display text-2xl font-bold text-brand-text sm:text-3xl">Como você prefere começar?</h1>
            <p className="mx-auto mt-3 max-w-2xl text-sm leading-6 text-brand-text-muted sm:text-base">
              Configure seu primeiro atendimento com ajuda ou conheça o aplicativo antes. Você poderá retomar a configuração pelo painel quando quiser.
            </p>
          </div>

          <div className="grid gap-4 p-5 sm:grid-cols-2 sm:p-8">
            <section className="relative flex flex-col rounded-3xl border-2 border-brand-primary bg-brand-primary/[0.035] p-6 shadow-sm">
              <span className="absolute right-5 top-5 rounded-full bg-brand-primary px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-white">Recomendado</span>
              <div className="mb-5 flex h-11 w-11 items-center justify-center rounded-2xl bg-brand-primary/10 text-brand-primary">
                <ListChecks size={22} />
              </div>
              <h2 className="font-display text-xl font-bold text-brand-text">Configurar com ajuda</h2>
              <p className="mt-2 flex-1 text-sm leading-6 text-brand-text-muted">
                Siga o passo a passo para cadastrar seu primeiro paciente, conectar o Google Docs e criar uma evolução.
              </p>
              <button
                type="button"
                onClick={() => void handleChooseStartMode('guided')}
                disabled={choosingMode !== null}
                className="btn-primary mt-6 w-full justify-center py-3 disabled:opacity-60"
              >
                {choosingMode === 'guided' ? <Loader2 size={16} className="mr-2 animate-spin" /> : <ArrowRight size={16} className="mr-2" />}
                Iniciar configuração guiada
              </button>
            </section>

            <section className="flex flex-col rounded-3xl border border-brand-border bg-white p-6 shadow-sm">
              <div className="mb-5 flex h-11 w-11 items-center justify-center rounded-2xl bg-brand-accent/15 text-brand-primary">
                <Compass size={22} />
              </div>
              <h2 className="font-display text-xl font-bold text-brand-text">Conhecer o aplicativo primeiro</h2>
              <p className="mt-2 flex-1 text-sm leading-6 text-brand-text-muted">
                Entre no painel, explore os recursos e conclua a preparação do seu espaço clínico quando estiver pronto.
              </p>
              <button
                type="button"
                onClick={() => void handleChooseStartMode('explore')}
                disabled={choosingMode !== null}
                className="btn-outline mt-6 w-full justify-center py-3 disabled:opacity-60"
              >
                {choosingMode === 'explore' ? <Loader2 size={16} className="mr-2 animate-spin" /> : <Compass size={16} className="mr-2" />}
                Explorar o aplicativo
              </button>
            </section>
          </div>

          {choiceError && (
