  const [prontuarioDocContent, setProntuarioDocContent] = useState('');

  // Estados de toggle Visualizar/Editar relatório
  const [reportEditMode, setReportEditMode] = useState(false);
  const [historyEditMode, setHistoryEditMode] = useState(false);

  // Estados para Assinatura Digital e Edição de Evolução
  const [editingEvolutionId, setEditingEvolutionId] = useState<string | null>(null);
  const [editingEvolutionText, setEditingEvolutionText] = useState('');
  const [editingEvolutionOriginalText, setEditingEvolutionOriginalText] = useState('');
  const [editingEvolutionTemplateId, setEditingEvolutionTemplateId] = useState<string>('');
  const [savingEvolutionId, setSavingEvolutionId] = useState<string | null>(null);
  const [convertingEvolutionId, setConvertingEvolutionId] = useState<string | null>(null);
  const [evolutionTemplates, setEvolutionTemplates] = useState<any[]>([]);
  const [signingEvolutionId, setSigningEvolutionId] = useState<string | null>(null);
  const [expandedEvoIds, setExpandedEvoIds] = useState<Record<string, boolean>>({});
  const [printSignatureInfo, setPrintSignatureInfo] = useState<any>(null);

  useEffect(() => {
    if (!editingEvolutionId) return;

    const previousHtmlOverscroll = document.documentElement.style.overscrollBehaviorY;
    const previousBodyOverscroll = document.body.style.overscrollBehaviorY;
    document.documentElement.style.overscrollBehaviorY = 'none';
    document.body.style.overscrollBehaviorY = 'none';

    return () => {
      document.documentElement.style.overscrollBehaviorY = previousHtmlOverscroll;
      document.body.style.overscrollBehaviorY = previousBodyOverscroll;
    };
  }, [editingEvolutionId]);

  const requestConfirmation = (options: Omit<ConfirmationDialogState, 'resolve'>) => {
    return new Promise<boolean>((resolve) => {
      setConfirmationDialog({ ...options, resolve });
    });
  };

  const resolveConfirmation = (confirmed: boolean) => {
    if (!confirmationDialog) return;
    const { resolve } = confirmationDialog;
    setConfirmationDialog(null);
    resolve(confirmed);
  };

  useEffect(() => {
    if (!confirmationDialog) return;

    const handleConfirmationKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        resolveConfirmation(false);
      }
    };

    window.addEventListener('keydown', handleConfirmationKeyDown);
    return () => window.removeEventListener('keydown', handleConfirmationKeyDown);
  }, [confirmationDialog]);

  // Estados para a busca semântica (RAG Clínico)
  const [semanticQuery, setSemanticQuery] = useState('');
  const [semanticLoading, setSemanticLoading] = useState(false);
  const [semanticAnswer, setSemanticAnswer] = useState<string | null>(null);
  const [semanticSources, setSemanticSources] = useState<any[]>([]);
  const [indexingPending, setIndexingPending] = useState(false);
  const [highlightedEvoId, setHighlightedEvoId] = useState<string | null>(null);

  const handleSemanticSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!semanticQuery.trim() || !id) return;

    if (!checkPlanActiveAndAlert("Pesquisa Inteligente por IA")) {
      return;
    }

    setSemanticLoading(true);
    setSemanticAnswer(null);
    setSemanticSources([]);

    try {
      const { data: { session } } = await supabase.auth.getSession();
      const token = session?.access_token;

      if (!token) {
        throw new Error("Sessão expirada. Faça login novamente.");
      }

      const response = await fetch(`/api/patients/${id}/semantic-search`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ query: semanticQuery.trim() })
      });

      const result = await response.json();

      if (response.status === 401) {
        alert("Sua sessão de acesso expirou por razões de segurança. Você será redirecionado para a tela de login.");
        await supabase.auth.signOut();
        navigate('/login');
        return;
      }

      if (!response.ok) {
        throw new Error(result.error || 'Erro ao realizar a busca semântica.');
      }

      setSemanticAnswer(result.answer);
      setSemanticSources(result.sources || []);

      // Recarregar dados para atualizar o estado local das evoluções (embeddings gerados sob demanda)
      await fetchData();
    } catch (error: any) {
      console.error("Erro na busca semântica:", error);
      alert("Erro na busca: " + (error.message || error));
    } finally {
      setSemanticLoading(false);
    }
  };

  const handleManualIndex = async () => {
    if (!id) return;

    if (!checkPlanActiveAndAlert("Pesquisa Inteligente por IA")) {
      return;
    }

    setIndexingPending(true);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const token = session?.access_token;

      if (!token) {
        throw new Error("Sessão expirada. Faça login novamente.");
      }

      const response = await fetch(`/api/patients/${id}/semantic-index`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      const result = await response.json();

      if (response.status === 401) {
        alert("Sua sessão de acesso expirou por razões de segurança. Você será redirecionado para a tela de login.");
        await supabase.auth.signOut();
        navigate('/login');
        return;
      }

      if (!response.ok) {
        throw new Error(result.error || 'Erro ao indexar evoluções.');
      }

      alert(result.message || 'Indexação concluída com sucesso!');
      await fetchData();
    } catch (error: any) {
      console.error("Erro ao indexar evoluções:", error);
      alert("Erro na indexação: " + (error.message || error));
    } finally {
      setIndexingPending(false);
    }
  };

  const scrollToAndExpandEvolution = (evoId: string) => {
    setExpandedEvoIds(prev => ({
      ...prev,
      [evoId]: true
    }));
    setHighlightedEvoId(evoId);

    setTimeout(() => {
      const element = document.getElementById(`evolution-card-${evoId}`);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }, 150);

    setTimeout(() => {
      setHighlightedEvoId(null);
    }, 3000);
  };

  const toggleEvoExpansion = (evoId: string) => {
    setExpandedEvoIds(prev => ({
      ...prev,
      [evoId]: !prev[evoId]
    }));
  };

  const reconnectGoogleAndResumeEvolutionEdit = async (recovery: EvolutionEditAuthRecovery) => {
    storeEvolutionEditAuthRecovery(recovery);
    evolutionEditAuthRecoveryRef.current = recovery;
    setGoogleAccessToken(null);

    const { error } = await requestGoogleOAuth({
      requiredScopes: 'clinicalDocs',
      currentGrantedScopes: googleGrantedScopes,
      redirectTo: getCurrentGoogleOAuthRedirectUrl(),
      loginHint: user?.email || undefined,
    });

    if (error) {
      throw new Error(error.message || 'Não foi possível renovar automaticamente a conexão com o Google.');
    }
  };

  const handleSaveEditedEvolution = async (
    evoId: string,
    recoveryDraft?: EvolutionEditAuthRecovery
  ) => {
    const evolutionText = recoveryDraft?.text ?? editingEvolutionText;
    const evolutionOriginalText = recoveryDraft?.originalText ?? editingEvolutionOriginalText;
    const evolutionTemplateId = recoveryDraft?.templateId ?? editingEvolutionTemplateId;

    if (!evolutionText.trim()) {
      alert("O texto da evolução não pode ser vazio.");
      return;
    }
    setSavingEvolutionId(evoId);
    try {
      const currentEvolution = evolutions.find((evo) => evo.id === evoId);
      if (!currentEvolution) throw new Error('Evolução não encontrada.');
      const previousText = currentEvolution.transcription_text || '';
      const previousTemplateId = currentEvolution.template_id || null;
      const previousUpdatedAt = currentEvolution.updated_at || null;
      const requiresGoogleSync = currentEvolution.google_doc_append_status === 'completed' && Boolean(patient?.google_doc_id);
      const authRecovery: EvolutionEditAuthRecovery = recoveryDraft || {
        userId: user?.id || '',
        patientId: patient?.id || id || '',
        evolutionId: evoId,
        text: evolutionText,
        originalText: evolutionOriginalText,
        templateId: evolutionTemplateId,
        activeMobileTab,
        savedAt: Date.now(),
      };

      if (requiresGoogleSync && (!hasFreshClinicalAccess || !googleAccessToken)) {
        await reconnectGoogleAndResumeEvolutionEdit({ ...authRecovery, savedAt: Date.now() });
        return;
      }

      const { error } = await supabase
        .from('evolutions')
        .update({
          transcription_text: evolutionText,
          template_id: evolutionTemplateId || null,
          updated_at: new Date().toISOString()
        })
        .eq('id', evoId);
      if (error) throw error;

      if (requiresGoogleSync && patient?.google_doc_id && googleAccessToken) {
        try {
          await replaceEvolutionInGoogleDoc(googleAccessToken, patient.google_doc_id, evoId, evolutionText);
        } catch (syncError) {
          const rollbackPayload: Record<string, string | null> = {
            transcription_text: previousText,
            template_id: previousTemplateId,
          };
          if (previousUpdatedAt) rollbackPayload.updated_at = previousUpdatedAt;
          const { error: rollbackError } = await supabase
            .from('evolutions')
            .update(rollbackPayload)
            .eq('id', evoId);

          if (rollbackError) {
            console.error('Erro ao restaurar a evolução após falha no Google Docs:', rollbackError);
          }

          if (isGoogleAuthenticationError(syncError)) {
            await reconnectGoogleAndResumeEvolutionEdit({ ...authRecovery, savedAt: Date.now() });
            return;
          }

          if (rollbackError) {
            throw new Error('A sincronização com o Google Docs falhou e a restauração automática na plataforma também não foi confirmada. Reabra a evolução antes de tentar novamente.');
          }
          throw syncError;
        }
      }

      clearEvolutionEditAuthRecovery();
      evolutionEditAuthRecoveryRef.current = null;
      setEditingEvolutionId(null);
      setEditingEvolutionText('');
      setEditingEvolutionOriginalText('');
      setEditingEvolutionTemplateId('');
      await fetchData();
      if (recoveryDraft) {
        setActiveMobileTab(recoveryDraft.activeMobileTab);
        scrollToAndExpandEvolution(evoId);
        alert("Conexão com o Google renovada e evolução atualizada com sucesso!");
      } else {
        alert("Evolução atualizada com sucesso!");
      }
    } catch (error: any) {
      console.error("Erro ao atualizar evolução:", error);
      if (isGoogleAuthenticationError(error)) {
        alert("Não foi possível renovar a conexão com o Google automaticamente. Sua edição foi preservada; toque novamente em Salvar alterações para tentar a reconexão.");
      } else {
        alert("Erro ao salvar alterações: " + (error.message || error));
      }
    } finally {
      setSavingEvolutionId(null);
    }
  };

  useEffect(() => {
    const recovery = evolutionEditAuthRecoveryRef.current;
    if (!recovery || !user?.id || loading) return;

    if (recovery.userId !== user.id || recovery.patientId !== id) {
      clearEvolutionEditAuthRecovery();
      evolutionEditAuthRecoveryRef.current = null;
      return;
    }

    if (!evolutionEditRecoveryRestoredRef.current) {
      evolutionEditRecoveryRestoredRef.current = true;
      setActiveMobileTab(recovery.activeMobileTab);
      setEditingEvolutionId(recovery.evolutionId);
      setEditingEvolutionText(recovery.text);
      setEditingEvolutionOriginalText(recovery.originalText);
      setEditingEvolutionTemplateId(recovery.templateId);
    }

    const evolutionStillExists = evolutions.some((evolution) => evolution.id === recovery.evolutionId);
    if (!evolutionStillExists || !patient?.google_doc_id || !hasFreshClinicalAccess) return;
    if (evolutionEditAutoResumeStartedRef.current) return;

    evolutionEditAutoResumeStartedRef.current = true;
    void handleSaveEditedEvolution(recovery.evolutionId, recovery);
  }, [evolutions, hasFreshClinicalAccess, id, loading, patient?.google_doc_id, user?.id]);

  const closeEvolutionEditor = () => {
    clearEvolutionEditAuthRecovery();
    evolutionEditAuthRecoveryRef.current = null;
    setEditingEvolutionId(null);
    setEditingEvolutionText('');
    setEditingEvolutionOriginalText('');
    setEditingEvolutionTemplateId('');
  };

  const handleConvertEditedEvolution = async (templateId: string) => {
    if (!editingEvolutionId || !editingEvolutionText.trim()) return;
    if (!editingEvolutionOriginalText.trim()) {
      alert('A transcrição original não está disponível para esta evolução antiga. O sistema não irá gerar um texto fictício para substituí-la.');
      return;
    }
    setConvertingEvolutionId(editingEvolutionId);
    try {
      const convertedText = await convertEvolutionToTemplate(editingEvolutionOriginalText, templateId || null);
      setEditingEvolutionText(convertedText);
      setEditingEvolutionTemplateId(templateId);
    } catch (error: any) {
      console.error('Erro ao converter modelo de evolução:', error);
      alert(error.message || 'Não foi possível converter a evolução.');
    } finally {
      setConvertingEvolutionId(null);
    }
  };

  const handleSaveToGoogleDocs = async (evo: any) => {
    if (!hasClinicalAccess || !googleAccessToken) {
      alert("Google Drive não autenticado. Por favor, conecte sua conta Google no painel.");
      return;
    }
    if (!patient?.google_doc_id) {
      alert("Este paciente não possui um documento de prontuário associado no Google Docs.");
      return;
    }

    setSyncingEvolutionId(evo.id);
    try {
      await appendToGoogleDoc(
        googleAccessToken,
        patient.google_doc_id,
        evo.session_date,
        evo.transcription_text,
        {
          sessionTime: evo.session_time || undefined,
          evolutionId: evo.id
        }
      );

      const { error } = await supabase
        .from('evolutions')
        .update({
          google_doc_append_status: 'completed',
          google_doc_append_at: new Date().toISOString()
        })
        .eq('id', evo.id);

      if (error) throw error;

      alert("Evolução salva no prontuário do Google Docs com sucesso!");
      await fetchData();
    } catch (err: any) {
      console.error("Erro ao salvar no Google Docs:", err);
      alert("Falha ao salvar no Google Docs: " + (err.message || err));
    } finally {
      setSyncingEvolutionId(null);
    }
  };

  const handleSignEvolutionDirectly = async (evoId: string) => {
    if (!checkPlanActiveAndAlert("Assinatura Digital")) {
      return;
    }
    const shouldSign = await requestConfirmation({
      title: 'Assinar e fechar evolução',
      message: 'A assinatura digital confirma a autoria e encerra esta evolução clínica.',
      warning: 'Após a confirmação, o conteúdo ficará imutável e não poderá mais ser alterado ou excluído.',
      confirmLabel: 'Assinar e fechar',
      cancelLabel: 'Voltar',
      icon: 'shield',
      variant: 'danger'
    });
    if (!shouldSign) {
      return;
    }
    setSigningEvolutionId(evoId);
    let evolutionSigned = false;
    try {
      // Assina no banco
      const { error } = await supabase
        .from('evolutions')
        .update({
          status: 'signed'
        })
        .eq('id', evoId);

      if (error) throw error;
      evolutionSigned = true;

      void sendNotification({
        title: "🔒 Evolução Assinada Digitalmente",
        content: `A evolução do paciente ${patient?.full_name} foi fechada e assinada com segurança no servidor.`,
        type: "success",
        link: `/painel/patients/${patient?.id}`
      });

      // Oferecer salvar o PDF na pasta do Google Drive do paciente
      if (hasClinicalAccess && googleAccessToken && patient?.target_folder_id) {
        const savePdf = await requestConfirmation({
          title: 'Salvar uma cópia no Google Drive?',
          message: 'A evolução assinada também pode ser salva como PDF na pasta do prontuário deste paciente.',
          confirmLabel: 'Salvar PDF',
          cancelLabel: 'Agora não',
          icon: 'download',
          variant: 'info'
        });
        if (savePdf) {
          let logoBase64 = null;
          const currentLogoUrl = getLogoUrl();
          if (currentLogoUrl) {
            try {
              logoBase64 = await getBase64ImageFromUrl(currentLogoUrl);
            } catch (err) {
              console.error("Error preloading logo:", err);
            }
          }
          const evoObj = evolutions.find(e => e.id === evoId);
          if (evoObj) {
            const doc = generateEvolutionPDF({ ...evoObj, status: 'signed' }, patient, professional, logoBase64);
            const pdfBlob = doc.output('blob');
            const cleanPatientName = (patient?.full_name || 'Paciente').replace(/\s+/g, '_');
            const cleanDate = evoObj.session_date
              ? evoObj.session_date.split('-').reverse().join('-')
              : new Date(evoObj.created_at).toLocaleDateString('pt-BR').replace(/\//g, '-');
            const fileName = `Evolucao_Clinica_${cleanPatientName}_${cleanDate}.pdf`;

            try {
              await uploadPdfToGoogleDrive(googleAccessToken, pdfBlob, fileName, patient.target_folder_id);
            } catch (uploadError) {
              console.error('A evolução foi assinada, mas não foi possível salvar o PDF no Google Drive:', uploadError);

              if (isGoogleAuthenticationError(uploadError)) {
                setGoogleAccessToken(null);
                const shouldReconnectGoogle = await requestConfirmation({
                  title: 'Evolução assinada; reconectar Google Drive?',
                  message: 'A assinatura foi concluída com segurança. A sessão do Google neste dispositivo expirou antes de salvar a cópia em PDF.',
                  warning: 'O PDF ainda não foi salvo. Após reconectar sua conta Google, use o botão “Salvar PDF” nesta evolução para concluir a cópia.',
                  confirmLabel: 'Reconectar Google',
                  cancelLabel: 'Agora não',
                  icon: 'shield',
                  variant: 'info'
                });

                if (shouldReconnectGoogle) {
                  await requestGoogleOAuth({
                    requiredScopes: 'clinicalDocs',
                    currentGrantedScopes: googleGrantedScopes,
                    redirectTo: getCurrentGoogleOAuthRedirectUrl()
                  });
                }
                await fetchData();
                return;
              }

              alert('Evolução assinada com sucesso, mas não foi possível salvar a cópia em PDF no Google Drive. Você pode tentar novamente pelo botão “Salvar PDF”.');
            }
          }
        }
      }

      alert(`Evolução assinada com sucesso!`);
      await fetchData();
    } catch (error: any) {
      console.error("Erro ao assinar evolução:", error);
      if (evolutionSigned) {
        alert('Evolução assinada com sucesso, mas ocorreu uma falha após a assinatura. Confira a evolução e, se necessário, tente salvar o PDF novamente.');
        await fetchData();
        return;
      }
      alert("Erro ao assinar evolução: " + (error.message || error));
    } finally {
      setSigningEvolutionId(null);
    }
  };

  const [signingReportId, setSigningReportId] = useState<string | null>(null);

  const handleSignReportDirectly = (reportId: string) => {
    setShowSignConfirmModal({ isOpen: true, reportId });
  };

  const executeReportSignature = async (reportId: string) => {
    if (!checkPlanActiveAndAlert("Assinatura Digital")) {
      return;
    }
    setSigningReportId(reportId);
    try {
      const { data: updatedReport, error } = await supabase
        .from('patient_reports')
        .update({
          status: 'signed'
        })
        .eq('id', reportId)
        .select()
        .single();

      if (error) throw error;

      void sendNotification({
        title: "🔒 Relatório Assinado Digitalmente",
        content: `O relatório do paciente ${patient?.full_name} foi fechado e assinado com segurança no servidor.`,
        type: "success",
        link: `/painel/patients/${patient?.id}`
      });

      alert(`Relatório assinado com sucesso!`);
      setViewingReport(updatedReport);
      setViewingReportContent(updatedReport.content);
      setOriginalReportContent(updatedReport.content);
      setHistoryEditMode(false);
      await fetchData();
    } catch (error: any) {
      console.error("Erro ao assinar relatório:", error);
      alert("Erro ao assinar relatório: " + (error.message || error));
    } finally {
      setSigningReportId(null);
    }
  };

  const handlePrintReport = (content: string, periodLabel: string, type: 'evolution_report' | 'pdi_draft', rep?: any) => {
    const originalTitle = document.title;
    const cleanPatientName = (patient?.full_name || 'Paciente').replace(/\s+/g, '_');
    const docLabel = type === 'evolution_report' ? 'Relatorio_Evolucao' : 'PDI';
    document.title = `${docLabel}_${cleanPatientName}`;

    if (rep && rep.status === 'signed') {
      setPrintSignatureInfo({
        method: rep.signature_method,
        date: rep.signature_date,
        ip: rep.signature_ip,
        hash: rep.signature_hash,
        name: rep.signed_by_name,
        register: rep.signed_by_register
      });
    } else {
      setPrintSignatureInfo(null);
    }

    setPrintMode('report');
    setPrintContent(getReportBodyContent(content));
    setPrintPeriodLabel(periodLabel);
    setPrintDocType(type === 'evolution_report' ? 'Relatório de Evolução Clínico' : 'Plano de Desenvolvimento Individual (PDI)');
    setTimeout(() => {
      window.print();
      document.title = originalTitle;
    }, 200);
  };

  const handlePrintProntuario = () => {
    if (!checkPlanActiveAndAlert("Filtro de Período na Impressão")) {
      return;
    }
    setShowPrintFilterModal(true);
  };

  const downloadGeneratedPdf = async (doc: jsPDF, fileName: string) => {
    try {
      const saved = await downloadPdfFile(doc, fileName);
      if (!saved) {
        throw new Error('O dispositivo não confirmou o salvamento do arquivo.');
      }
    } catch (error) {
      console.error('[PDF] Não foi possível baixar o arquivo:', error);
      alert('Não foi possível baixar o PDF. Verifique o armazenamento do dispositivo e tente novamente.');
    }
  };

  const downloadProntuarioPdf = async (content: string, documentType: string, periodLabel = '') => {
    let logoBase64: string | null = null;
    const logoUrl = getLogoUrl();
    if (logoUrl) {
      try {
        logoBase64 = await getBase64ImageFromUrl(logoUrl);
      } catch (error) {
        console.warn('[PDF] Continuando sem logotipo:', error);
      }
    }

    const doc = generateProntuarioPDF({
      content,
      patient,
      professional,
      siteConfig,
      documentType,
      periodLabel,
      logoBase64,
      customLogoSettings: professional?.custom_logo_settings
    });
    const saved = await downloadPdfFile(doc, getProntuarioPdfFileName(patient?.full_name));
    if (!saved) {
      throw new Error('Não foi possível salvar o arquivo do prontuário.');
    }
  };

  const handleExecutePrintProntuario = async () => {
    setPrintSignatureInfo(null);
    setShowPrintFilterModal(false);

    if (printSource === 'google_doc') {
      if (!patient?.google_doc_id) {
        alert("Nenhum prontuário do Google Docs vinculado a este paciente.");
        return;
      }

      if (!hasClinicalAccess) {
        alert("Para ler o prontuário no Google Docs, precisamos renovar seu acesso à sua conta Google. Você será redirecionado.");
        await requestGoogleOAuth({
          requiredScopes: 'clinicalDocs',
          currentGrantedScopes: googleGrantedScopes,
          redirectTo: getCurrentGoogleOAuthRedirectUrl()
        });
        return;
      }

      setPrintingProntuario(true);
      const originalTitle = document.title;
      const cleanPatientName = (patient?.full_name || 'Paciente').replace(/\s+/g, '_');
      document.title = `Prontuario_Evolucoes_${cleanPatientName}`;

      try {
        const content = await getGoogleDocContent(googleAccessToken, patient.google_doc_id);
        await downloadProntuarioPdf(content, 'Prontuário de Evoluções Clínicas (Google Docs)');
        document.title = originalTitle;
        setPrintingProntuario(false);
        alert('Prontuário gerado com sucesso. O download do arquivo PDF será iniciado automaticamente. No Android, o arquivo ficará na pasta Downloads.');
      } catch (err: any) {
        console.error("Erro ao carregar prontuário do Google Docs:", err);
        document.title = originalTitle;
        setPrintingProntuario(false);

        if (isGoogleAuthenticationError(err)) {
          setGoogleAccessToken(null);
          try {
            const { error: reauthenticationError } = await requestGoogleOAuth({
              requiredScopes: 'clinicalDocs',
              currentGrantedScopes: googleGrantedScopes,
              redirectTo: getCurrentGoogleOAuthRedirectUrl(),
              prompt: 'consent',
              loginHint: user?.email || undefined
            });

            if (reauthenticationError) throw reauthenticationError;
            return;
          } catch (reauthenticationError: any) {
            console.error('Erro ao renovar autenticação do Google:', reauthenticationError);
            alert('Sua sessão do Google expirou. Não foi possível renová-la automaticamente. Tente novamente.');
          }
          return;
        }

        alert("Erro ao ler prontuário do Google Docs: " + (err.message || err));
      }
    } else {
      // Platform Database Evolutions
      if (evolutions.length === 0) {
        alert("Não há evoluções cadastradas nesta plataforma para este paciente.");
        return;
      }

      const start = printStartDate ? new Date(printStartDate + 'T00:00:00') : null;
      const end = printEndDate ? new Date(printEndDate + 'T23:59:59') : null;

      const filtered = evolutions.filter(evo => {
        const d = new Date(evo.created_at);
        return (!start || d >= start) && (!end || d <= end);
      }).sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());

      if (filtered.length === 0) {
        alert("Nenhuma evolução encontrada no período selecionado.");
        return;
      }

      setPrintingProntuario(true);
      const originalTitle = document.title;
      const cleanPatientName = (patient?.full_name || 'Paciente').replace(/\s+/g, '_');
      document.title = `Prontuario_Evolucoes_${cleanPatientName}`;

      let contentText = "";
      filtered.forEach((evo) => {
        const dateStr = formatDateTime(evo.created_at);
        const signedInfo = evo.status === 'signed'
          ? `[Documento Assinado Digitalmente por: ${evo.signed_by_name || 'Profissional'} (${evo.signed_by_register || ''}) em ${new Date(evo.signature_date).toLocaleString('pt-BR')}]`
          : '[Rascunho]';

        contentText += `======================================================================\n`;
        contentText += `EVOLUÇÃO CLÍNICA - DATA: ${dateStr} - ${signedInfo}\n`;
        contentText += `======================================================================\n\n`;
        contentText += `${evo.transcription_text || evo.content || ''}\n\n\n`;
      });

      setProntuarioDocContent(contentText);
      const periodLabel = start && end
        ? `De ${start.toLocaleDateString('pt-BR')} até ${end.toLocaleDateString('pt-BR')}` 
        : start 
          ? `A partir de ${start.toLocaleDateString('pt-BR')}` 
          : end 
            ? `Até ${end.toLocaleDateString('pt-BR')}` 
            : 'Todo o Período';

      try {
        await downloadProntuarioPdf(contentText, 'Prontuário de Evoluções Clínicas (Plataforma)', periodLabel);
        document.title = originalTitle;
        setPrintingProntuario(false);
        alert('Prontuário gerado com sucesso. O download do arquivo PDF será iniciado automaticamente. No Android, o arquivo ficará na pasta Downloads.');
      } catch (err: any) {
        console.error('Erro ao gerar PDF do prontuário:', err);
        document.title = originalTitle;
        setPrintingProntuario(false);
        alert('Erro ao gerar o arquivo do prontuário: ' + (err.message || err));
      }
    }
  };

