import { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { useAuthStore } from '../store/authStore';
import { Link } from 'react-router-dom';
import { Activity, Bell, Calendar, FileText, MessageCircle, Plus, Search } from 'lucide-react';
import { PanelPageHeader } from '../components/layout/PanelPageHeader';

type PatientEvolution = {
  patient_id: string;
  session_date: string | null;
  session_time: string | null;
  created_at: string | null;
};

type PatientEvolutionSummary = {
  count: number;
  last: PatientEvolution | null;
};

const WEEKDAY_LABELS = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];

const calculateAge = (birthDate: string | null | undefined): number | null => {
  if (!birthDate) return null;

  const [year, month, day] = birthDate.split('-').map(Number);
  if (!year || !month || !day) return null;

  const today = new Date();
  const birth = new Date(year, month - 1, day);
  if (Number.isNaN(birth.getTime()) || birth > today) return null;

  let age = today.getFullYear() - year;
  const hasHadBirthday = today.getMonth() + 1 > month
    || (today.getMonth() + 1 === month && today.getDate() >= day);
  if (!hasHadBirthday) age -= 1;

  return age >= 0 ? age : null;
};

const formatDate = (date: string | null | undefined): string => {
  if (!date) return '';
  const datePart = date.substring(0, 10);
  const [year, month, day] = datePart.split('-');
  if (year && month && day) return `${day}/${month}/${year}`;

  const parsed = new Date(date);
  return Number.isNaN(parsed.getTime()) ? '' : parsed.toLocaleDateString('pt-BR');
};

const getEvolutionTimestamp = (evolution: PatientEvolution): number => {
  const dateValue = evolution.session_date
    ? `${evolution.session_date}T${evolution.session_time || '00:00:00'}`
    : evolution.created_at || '';
  const timestamp = new Date(dateValue).getTime();
  return Number.isNaN(timestamp) ? 0 : timestamp;
};

const getWhatsAppUrl = (phone: string | null | undefined): string | null => {
  const cleanPhone = String(phone || '').replace(/\D/g, '');
  if (!cleanPhone) return null;

  const isMobile = typeof navigator !== 'undefined'
    && /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);

  return isMobile
    ? `https://wa.me/${cleanPhone}`
    : `https://web.whatsapp.com/send?phone=${cleanPhone}`;
};

const getReminderLabel = (patient: any): string | null => {
  if (!patient.evolution_reminder_active) return null;

  const days = Array.isArray(patient.session_days)
    ? patient.session_days
      .filter((day: unknown): day is number => typeof day === 'number' && Number.isInteger(day) && day >= 0 && day <= 6)
      .sort((a: number, b: number) => a - b)
      .map((day: number) => WEEKDAY_LABELS[day])
    : [];
  const time = patient.session_time ? String(patient.session_time).substring(0, 5) : '';

  if (!days.length || !time) return 'Lembrete ativo';
  return `Lembrete: ${days.join(', ')} · ${time}`;
};

export default function Patients() {
  const { user } = useAuthStore();
  const [patients, setPatients] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const fetchPatients = async () => {
      if (!user) return;
      try {
        const [patientsResult, evolutionsResult] = await Promise.all([
          supabase
            .from('patients')
            .select('*')
            .eq('professional_id', user.id)
            .order('full_name'),
          supabase
            .from('evolutions')
            .select('patient_id, session_date, session_time, created_at')
            .eq('professional_id', user.id)
            .eq('transcription_status', 'completed')
        ]);

        if (patientsResult.error) throw patientsResult.error;
        if (evolutionsResult.error) throw evolutionsResult.error;

        const evolutionSummaries = new Map<string, PatientEvolutionSummary>();
        for (const evolution of (evolutionsResult.data || []) as PatientEvolution[]) {
          const current = evolutionSummaries.get(evolution.patient_id) || { count: 0, last: null };
          current.count += 1;
          if (!current.last || getEvolutionTimestamp(evolution) > getEvolutionTimestamp(current.last)) {
            current.last = evolution;
          }
          evolutionSummaries.set(evolution.patient_id, current);
        }

        setPatients((patientsResult.data || []).map((patient) => ({
          ...patient,
          evolutionSummary: evolutionSummaries.get(patient.id) || { count: 0, last: null }
        })));
      } catch (error) {
        console.error("Error fetching patients:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchPatients();
  }, [user]);

  const filteredPatients = patients.filter(p => 
    p.full_name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <PanelPageHeader
        icon={Activity}
        title="Pacientes"
        actions={<Link
          to="/painel/patients/new" 
          className="btn-primary"
        >
          <Plus size={20} className="mr-2" />
          <span>Novo Paciente</span>
        </Link>}
      />

      <div className="card p-4">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-brand-text-muted" size={20} />
          <input 
            type="text"
            placeholder="Buscar paciente por nome..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="input-field pl-10 pr-4 py-2"
          />
        </div>
      </div>

      <div className="card">
        {loading ? (
          <div className="p-8 text-center text-brand-text-muted">Carregando pacientes...</div>
        ) : filteredPatients.length === 0 ? (
          <div className="p-8 text-center text-brand-text-muted">Nenhum paciente encontrado.</div>
        ) : (
          <div className="divide-y divide-brand-border">
            {filteredPatients.map((patient) => (
              <div key={patient.id} className="p-4 sm:p-6 flex flex-col sm:flex-row sm:items-center justify-between hover:bg-brand-bg transition-colors gap-4">
                <div>
                  <h3 className="font-semibold text-brand-text text-lg">{patient.full_name}</h3>
                  <div className="flex items-center space-x-2 mt-1">
                    <span className={`px-2 py-1 text-xs rounded-full ${patient.status === 'active' ? 'bg-brand-accent/20 text-brand-primary' : 'bg-gray-100 text-gray-700'}`}>
                      {patient.status === 'active' ? 'Ativo' : 'Inativo'}
                    </span>
                    {patient.google_doc_id && (
                      <span className="flex items-center text-xs text-brand-primary bg-brand-primary/10 px-2 py-1 rounded-full">
                        <FileText size={12} className="mr-1" />
                        Prontuário Vinculado
                      </span>
                    )}
                  </div>
                  <div className="flex flex-wrap items-center gap-x-4 gap-y-2 mt-3 text-xs text-brand-text-muted">
                    {calculateAge(patient.birth_date) !== null && (
                      <span className="inline-flex items-center gap-1 whitespace-nowrap">
                        <Calendar size={13} />
                        {calculateAge(patient.birth_date)} {calculateAge(patient.birth_date) === 1 ? 'ano' : 'anos'}
                      </span>
                    )}
                    {patient.evolutionSummary?.last && (
                      <span className="inline-flex items-center gap-1 whitespace-nowrap">
                        <Calendar size={13} />
                        Último atendimento: {formatDate(patient.evolutionSummary.last.session_date || patient.evolutionSummary.last.created_at)}
                        {patient.evolutionSummary.last.session_time && `, ${patient.evolutionSummary.last.session_time.substring(0, 5)}`}
                      </span>
                    )}
                    <span className="inline-flex items-center gap-1 whitespace-nowrap">
                      <Activity size={13} />
                      {patient.evolutionSummary?.count || 0} {patient.evolutionSummary?.count === 1 ? 'evolução' : 'evoluções'}
                    </span>
                    {getReminderLabel(patient) && (
                      <span className="inline-flex items-center gap-1 whitespace-nowrap">
                        <Bell size={13} />
                        {getReminderLabel(patient)}
                      </span>
                    )}
                    {getWhatsAppUrl(patient.phone) && (
                      <a
                        href={getWhatsAppUrl(patient.phone) || undefined}
                        target="_blank"
                        rel="noopener noreferrer"
                        aria-label={`Abrir WhatsApp de ${patient.full_name}`}
                        className="inline-flex items-center gap-1 whitespace-nowrap text-emerald-700 hover:text-emerald-800 hover:underline"
                      >
                        <MessageCircle size={13} />
                        WhatsApp
                      </a>
                    )}
                  </div>
                </div>
                <div className="flex items-center space-x-3">
                  <Link 
                    to={`/painel/patients/${patient.id}`}
                    className="btn-outline"
                  >
                    Ver Detalhes
                  </Link>
                  <Link 
                    to={`/painel/patients/${patient.id}/evolutions/new`}
                    className="btn-primary bg-brand-primary/10 text-brand-primary hover:bg-brand-primary hover:text-white border-transparent"
                  >
                    Nova Evolução
                  </Link>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

src/pages/PendingApproval.tsx:
import React, { useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { supabase } from '../supabaseClient';
import { useAuthStore } from '../store/authStore';
import { Clock, ShieldAlert, LogOut, Sparkles } from 'lucide-react';
import { AppVersion } from '../components/layout/AppVersion';
import { useSiteConfig } from '../hooks/useSiteConfig';
import { appendBrandAssetVersion, getBrandAssetSignature } from '../utils/brandAssets';
import { getOnboardingDestination, isOnboardingComplete } from '../utils/onboarding';

export default function PendingApproval() {
  const { user, profileStatus, profileRole, subscriptionStatus, subscriptionEndsAt, setUser, setProfileInfo } = useAuthStore();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const siteConfig = useSiteConfig();
  const assetSignature = getBrandAssetSignature(siteConfig);
  const isInactive = searchParams.get('status') === 'inactive' || profileStatus === 'inactive';

  useEffect(() => {
    // Redireciona de volta se não estiver autenticado
    if (!user) {
      navigate('/login', { replace: true });
    } else if (profileStatus === 'active') {
      const isPendingCheckoutFlow = sessionStorage.getItem('pending_checkout_flow') === 'true';
      const now = new Date();
      const endsAt = subscriptionEndsAt ? new Date(subscriptionEndsAt) : null;
      const isExpired = endsAt ? endsAt < now : false;
      const isActive = isPendingCheckoutFlow
        ? subscriptionStatus === 'active'
        : (subscriptionStatus === 'active' || subscriptionStatus === 'trialing');

      if (profileRole === 'admin') {
        navigate('/admin/professionals', { replace: true });
      } else if (isPendingCheckoutFlow && (!isActive || isExpired)) {
        navigate('/checkout', { replace: true });
      } else if (!isOnboardingComplete(user.id)) {
        navigate(getOnboardingDestination(user.id), { replace: true });
      } else {
        // Se já estiver ativo, pode ir direto para a raiz
        navigate('/painel/dashboard', { replace: true });
      }
    }
  }, [user, profileStatus, profileRole, subscriptionStatus, subscriptionEndsAt, navigate]);

  useEffect(() => {
    if (!user || profileStatus === 'active') {
      return;
    }

    let cancelled = false;

    const syncAccess = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        const session = sessionData.session;

        if (!session || cancelled) {
          return;
        }

        const response = await fetch('/api/onboarding/bootstrap', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${session.access_token}`
          }
        });

        const data = await response.json().catch(() => ({}));

        if (!response.ok || cancelled) {
          return;
        }

        const profile = data.profile || {};
        const nextStatus = profile.status || data.status || 'pending';

        setProfileInfo(
          nextStatus,
          profile.role || 'therapist',
          profile.subscription_plan || 'trial',
          profile.subscription_status || 'trialing',
          profile.subscription_ends_at || null,
          profile.trial_ends_at || null
        );
      } catch (error) {
        console.error('Erro ao sincronizar acesso pendente:', error);
      }
    };

    void syncAccess();
    const interval = window.setInterval(syncAccess, 15000);

    return () => {
      cancelled = true;
      window.clearInterval(interval);
    };
  }, [user, profileStatus, navigate, setProfileInfo]);

  const handleLogout = async () => {
    try {
      await supabase.auth.signOut();
      setUser(null);
      setProfileInfo(null, null);
      navigate('/login', { replace: true });
    } catch (error) {
      console.error('Erro ao deslogar:', error);
    }
  };

  return (
    <div className="min-h-screen bg-brand-bg flex flex-col justify-center py-12 px-6 sm:px-6 lg:px-8 relative overflow-hidden">
      {/* Elementos decorativos de fundo */}
      <div className="absolute top-0 left-0 w-full h-64 bg-gradient-to-b from-brand-primary/10 to-transparent pointer-events-none" />
      <div className="absolute -top-24 -right-24 w-96 h-96 bg-brand-accent/5 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute -bottom-24 -left-24 w-96 h-96 bg-brand-primary/5 rounded-full blur-3xl pointer-events-none" />

      <div className="sm:mx-auto sm:w-full sm:max-w-md relative z-10 text-center">
        <div className="flex justify-center mb-6">
          {(siteConfig.logo_light_url || siteConfig.logo_dark_url) ? (
            <div className="p-3 bg-white rounded-3xl shadow-xl shadow-brand-primary/10 border border-brand-primary/5">
              <img
                src={appendBrandAssetVersion(siteConfig.logo_light_url || siteConfig.logo_dark_url, assetSignature)}
                alt="Evolução Clínica"
                className="h-20 w-auto object-contain p-2"
              />
            </div>
          ) : (
            <h2 className="mt-4 text-center text-2xl font-display font-bold text-brand-primary tracking-tight">
              {siteConfig.pwa_app_name || "Evolução Clínica"}
            </h2>
          )}
        </div>
        {siteConfig.logo_light_url && (
          <h2 className="mt-4 text-center text-2xl font-display font-bold text-brand-primary tracking-tight">
            {siteConfig.pwa_app_name || "Evolução Clínica"}
          </h2>
        )}
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md relative z-10">
        <div className="card shadow-2xl shadow-brand-primary/5 py-10 px-6 sm:px-10 bg-white/80 backdrop-blur-sm border-brand-primary/10 text-center">
          <div className="flex flex-col items-center">
            {isInactive ? (
              <>
                <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center border border-red-100 mb-6 animate-pulse">
                  <ShieldAlert className="w-8 h-8 text-red-600" />
                </div>
                <h3 className="text-xl font-display font-bold text-red-600 mb-3">
                  Cadastro Inativo
                </h3>
                <p className="text-sm text-brand-text-muted leading-relaxed mb-8">
                  O acesso à sua conta na plataforma foi desativado temporariamente. Se você acredita que isso é um engano ou precisa de suporte técnico, entre em contato com a administração.
                </p>
              </>
            ) : (
              <>
                <div className="w-16 h-16 bg-brand-accent/10 rounded-2xl flex items-center justify-center border border-brand-accent/20 mb-6">
                  <Clock className="w-8 h-8 text-brand-primary animate-pulse" />
                </div>
                <h3 className="text-xl font-display font-bold text-brand-primary mb-3">
                  Aguardando Aprovação
                </h3>
                <p className="text-sm text-brand-text-muted leading-relaxed mb-8">
                  Seu cadastro foi recebido com sucesso! Para garantir a segurança dos dados, novos acessos passam por análise. Você terá acesso aos recursos da plataforma assim que seu perfil for aprovado por um administrador.
                </p>
              </>
            )}

            <div className="w-full border-t border-brand-border/60 pt-6 mb-4">
              <div className="flex items-center justify-center space-x-3 text-xs text-brand-text mb-4">
                <span className="font-semibold">{user?.user_metadata?.full_name || user?.email}</span>
                <span className="text-brand-text-muted">({user?.email})</span>
              </div>
            </div>

            <button
              onClick={handleLogout}
              className="w-full inline-flex items-center justify-center px-4 py-3 border border-brand-border text-sm font-medium rounded-xl text-brand-text bg-white hover:bg-brand-bg hover:border-brand-primary/30 transition-all duration-200 active:scale-95 shadow-sm hover:shadow flex items-center justify-center space-x-2"
            >
              <LogOut className="w-4 h-4 text-brand-text-muted" />
              <span>Sair e acessar com outra conta</span>
            </button>
          </div>

          <div className="mt-8 flex items-center justify-center space-x-2 text-brand-primary/60">
            <Sparkles className="w-4 h-4" />
            <p className="text-xs font-medium uppercase tracking-widest italic">Evolução Clínica</p>
          </div>
        </div>
      </div>

      <div className="mt-auto pt-8 relative z-10 text-center">
        <div className="inline-block px-4 py-1.5 bg-white/50 backdrop-blur-md rounded-full border border-brand-primary/5 shadow-sm">
          <AppVersion />
        </div>
      </div>
    </div>
  );
}
